    11→// Test handling of repeated dependencies in the graph
    12→TEST(BatchOperationsTest, TestRepeatDependency) {
    13→    // ds → A, ds → a, A → a
    14→    auto a = reaction::var(1).setName("a");
    15→    auto b = reaction::var(2).setName("b");
    16→
    17→    int triggerCount = 0;
    18→    auto dsA = reaction::calc([&]() { return a() + b(); }).setName("dsA");
    19→
    20→    auto dsB = reaction::calc([&]() {++triggerCount; return a() + dsA(); }).setName("dsB");
    21→
    22→    triggerCount = 0;
    23→
    24→    reaction::batchExecute([&]() { a.value(2); });
