   319→
   320→    auto calc1 = reaction::calc([&]() { return var1() + var2(); }).setName("calc1");
   321→    auto calc2 = reaction::calc([&]() { return calc1() * 2; }).setName("calc2");
   322→    auto calc3 = reaction::calc([&]() { return calc2() + 1; }).setName("calc3");
   323→
   324→    auto calc4 = reaction::calc([&]() { return var2() + var3(); }).setName("calc4");
   325→    auto calc5 = reaction::calc([&]() { return calc4() * 3; }).setName("calc5");
   326→
   327→    auto calc6 = reaction::calc([&]() { return var3() + var4(); }).setName("calc6");
   328→    auto calc7 = reaction::calc([&]() { return calc6() * 4; }).setName("calc7");
   329→
   330→    auto calc8 = reaction::calc([&]() { return var4() * 2; }).setName("calc8");
   331→    auto calc9 = reaction::calc([&]() { return calc8() + 5; }).setName("calc9");
