    11→/**
    12→ * @brief Test comparison operators in expression templates
    13→ *
    14→ * This test verifies that all comparison operators work correctly
    15→ * with reactive values in expression templates.
    16→ */
    17→TEST(ExpressionOperatorsTest, TestComparisonOperators) {
    18→    using namespace reaction;
    19→
    20→    auto a = var(5).setName("a");
    21→    auto b = var(3).setName("b");
    22→    auto c = var(5).setName("c");
    23→
    24→    // Test equality
    25→    auto eq_expr = expr(a == c).setName("eq_expr");
    26→    EXPECT_TRUE(eq_expr.get());
    27→
    28→    auto neq_expr = expr(a == b).setName("neq_expr");
    29→    EXPECT_FALSE(neq_expr.get());
    30→
    31→    // Test inequality
    32→    auto ne_expr = expr(a != b).setName("ne_expr");
    33→    EXPECT_TRUE(ne_expr.get());
    34→
    35→    auto ne_expr2 = expr(a != c).setName("ne_expr2");
    36→    EXPECT_FALSE(ne_expr2.get());
    37→
    38→    // Test less than
    39→    auto lt_expr = expr(b < a).setName("lt_expr");
    40→    EXPECT_TRUE(lt_expr.get());
    41→
    42→    auto lt_expr2 = expr(a < b).setName("lt_expr2");
    43→    EXPECT_FALSE(lt_expr2.get());
    44→
    45→    // Test greater than
    46→    auto gt_expr = expr(a > b).setName("gt_expr");
    47→    EXPECT_TRUE(gt_expr.get());
    48→
    49→    auto gt_expr2 = expr(b > a).setName("gt_expr2");
    50→    EXPECT_FALSE(gt_expr2.get());
    51→
    52→    // Test less than or equal
    53→    auto le_expr = expr(b <= a).setName("le_expr");
    54→    EXPECT_TRUE(le_expr.get());
    55→
    56→    auto le_expr2 = expr(a <= c).setName("le_expr2");
    57→    EXPECT_TRUE(le_expr2.get());
    58→
    59→    // Test greater than or equal
    60→    auto ge_expr = expr(a >= b).setName("ge_expr");
    61→    EXPECT_TRUE(ge_expr.get());
    62→
    63→    auto ge_expr2 = expr(a >= c).setName("ge_expr2");
    64→    EXPECT_TRUE(ge_expr2.get());
    65→
    66→    // Test dynamic updates
    67→    b.value(7);
    68→    EXPECT_FALSE(lt_expr.get()); // 7 < 5 is false
    69→    EXPECT_TRUE(gt_expr2.get()); // 7 > 5 is true
    70→}
