   362→    EXPECT_THROW(calc8.reset([&]() { return var4() + 10; }), std::runtime_error);
   363→    EXPECT_THROW(calc9.reset([&]() { return calc8() * 3; }), std::runtime_error);
   364→    EXPECT_THROW(calc10.reset([&]() { return calc9() + 50; }), std::runtime_error);
   365→
   366→    // Verify values haven't changed (batch constructor doesn't execute the function)
   367→    EXPECT_EQ(calc1.get(), 3);
   368→    EXPECT_EQ(calc2.get(), 6);
   369→    EXPECT_EQ(calc3.get(), 7);
   370→
   371→    // Execute the batch
   372→    batch.execute();
   373→
   374→    // Now values should be updated
   375→    EXPECT_EQ(var1.get(), 10);
   376→    EXPECT_EQ(var2.get(), 20);
   377→    EXPECT_EQ(var3.get(), 30);
   378→    EXPECT_EQ(var4.get(), 40);
   379→
   380→    EXPECT_EQ(calc1.get(), 30);   // 10 + 20
   381→    EXPECT_EQ(calc2.get(), 60);   // 30 * 2
   382→    EXPECT_EQ(calc3.get(), 61);   // 60 + 1
   383→    EXPECT_EQ(calc4.get(), 50);   // 20 + 30
   384→    EXPECT_EQ(calc5.get(), 150);  // 50 * 3
   385→    EXPECT_EQ(calc6.get(), 70);   // 30 + 40
   386→    EXPECT_EQ(calc7.get(), 280);  // 70 * 4
   387→    EXPECT_EQ(calc8.get(), 80);   // 40 * 2
   388→    EXPECT_EQ(calc9.get(), 85);   // 80 + 5
   389→    EXPECT_EQ(calc10.get(), 170); // 85 * 2
   390→
   391→    // After batch execution, it's still active, so reset should still be prevented
   392→    EXPECT_THROW(calc1.reset([&]() { return var1() * 2; }), std::runtime_error);
   393→
   394→    // Manually close the batch
   395→    batch.close();
   396→
   397→    // Now reset operations should work
   398→    EXPECT_NO_THROW(calc1.reset([&]() { return var1() * 2; }));
   399→    EXPECT_EQ(calc1.get(), 20); // 10 * 2
   400→
   401→    // This should propagate through the dependency chain
   402→    EXPECT_EQ(calc2.get(), 40); // 20 * 2
   403→    EXPECT_EQ(calc3.get(), 41); // 40 + 1
   404→
   405→    // Test that other nodes can also be reset
   406→    EXPECT_NO_THROW(calc5.reset([&]() { return calc4() + 1000; }));
   407→    EXPECT_EQ(calc5.get(), 1050); // 50 + 1000
   408→
   409→    // Test that batch is indeed closed
   410→    EXPECT_TRUE(batch.isClosed());
   411→}
