   239→/**
   240→ * @brief Expression specialization for reactive variables.
   241→ *
   242→ * Allows manual setting and change detection.
   243→ */
   244→template <typename Type, IsTrigger TR>
   245→class Expression<VarExpr, Type, TR> : public Resource<Type> {
   246→public:
   247→    using Resource<Type>::Resource;
   248→
   249→    template <typename T>
   250→    void setValue(T &&t) {
   251→        bool changed = this->updateValue(std::forward<T>(t));
   252→        if (!g_batch_execute) {
   253→            this->notify(changed);
   254→        }
   255→    }
   256→};
