   413→/**
   414→ * @brief Test multiple batches with overlapping data sources and complex dependencies
   415→ *
   416→ * This test verifies:
   417→ * 1. Multiple batches can be created and executed sequentially
   418→ * 2. Batches with overlapping data sources don't interfere
   419→ * 3. Complex dependency graphs with repeated nodes are handled correctly
   420→ * 4. State is properly maintained between batch executions
   421→ */
   422→TEST(BatchOperationsTest, TestMultipleBatchesWithSharedDependencies) {
   423→    // Create shared data sources
   424→    auto a = reaction::var(1).setName("a");
   425→    auto b = reaction::var(2).setName("b");
   426→    auto c = reaction::var(3).setName("c");
   427→
   428→    // Create computed values with complex dependencies
   429→    auto X = reaction::calc([&]() { return a() + b(); }).setName("X");
   430→    auto Y = reaction::calc([&]() { return b() * c(); }).setName("Y");
   431→    auto Z = reaction::calc([&]() { return X() + Y(); }).setName("Z");
   432→
   433→    // Trackers for computed values
   434→    int triggerCountX = 0, triggerCountY = 0, triggerCountZ = 0;
   435→    int triggerCountA = 0, triggerCountB = 0, triggerCountC = 0;
   436→
   437→    // Create observers with complex dependencies
   438→    auto obs1 = reaction::calc([&]() {
   439→        triggerCountX++;
   440→        return X() + c();
   441→    }).setName("obs1");
   442→
   443→    auto obs2 = reaction::calc([&]() {
   444→        triggerCountY++;
   445→        return Y() + a();
   446→    }).setName("obs2");
   447→
   448→    auto obs3 = reaction::calc([&]() {
   449→        triggerCountZ++;
   450→        return Z() + obs1() + obs2();
   451→    }).setName("obs3");
   452→
   453→    auto obs4 = reaction::calc([&]() {
   454→        triggerCountA++;
   455→        return a() + obs3();
   456→    }).setName("obs4");
   457→
   458→    auto obs5 = reaction::calc([&]() {
   459→        triggerCountB++;
   460→        return b() + obs4();
   461→    }).setName("obs5");
   462→
   463→    auto obs6 = reaction::calc([&]() {
   464→        triggerCountC++;
   465→        return c() + obs5() + obs3();
   466→    }).setName("obs6");
   467→
   468→    // Precompute initial values
   469→    EXPECT_EQ(X.get(), 3);     // 1+2
   470→    EXPECT_EQ(Y.get(), 6);     // 2*3
   471→    EXPECT_EQ(Z.get(), 9);     // 3+6
   472→    EXPECT_EQ(obs1.get(), 6);  // 3+3
   473→    EXPECT_EQ(obs2.get(), 7);  // 6+1
   474→    EXPECT_EQ(obs3.get(), 22); // 9+6+7
   475→    EXPECT_EQ(obs4.get(), 23); // 1+22
   476→    EXPECT_EQ(obs5.get(), 25); // 2+23
   477→    EXPECT_EQ(obs6.get(), 50); // 3+25+22
   478→
   479→    // Reset counters
   480→    triggerCountX = triggerCountY = triggerCountZ = 0;
   481→    triggerCountA = triggerCountB = triggerCountC = 0;
   482→
   483→    // Create multiple batches (but don't execute yet)
   484→    auto batch1 = reaction::batch([&]() {
   485→        a.value(10); // Affects X, obs2, obs4, and all downstream
   486→    });
   487→
   488→    auto batch2 = reaction::batch([&]() {
   489→        b.value(20); // Affects X, Y, and all downstream
   490→        c.value(30); // Affects Y, obs1, obs6, and all downstream
   491→    });
   492→
   493→    auto batch3 = reaction::batch([&]() {
   494→        a.value(100); // Overrides previous a change
   495→        c.value(300); // Overrides previous c change
   496→    });
   497→
   498→    // Verify state hasn't changed yet
   499→    EXPECT_EQ(a.get(), 1);
   500→    EXPECT_EQ(b.get(), 2);
   501→    EXPECT_EQ(c.get(), 3);
   502→    EXPECT_EQ(obs6.get(), 50);
   503→    EXPECT_EQ(triggerCountX, 0);
   504→    EXPECT_EQ(triggerCountA, 0);
   505→
   506→    // Execute batches in sequence
   507→    batch1.execute(); // Only a changes to 10
   508→
   509→    // Verify after batch1
   510→    EXPECT_EQ(a.get(), 10);
   511→    EXPECT_EQ(b.get(), 2);
   512→    EXPECT_EQ(c.get(), 3);
   513→    EXPECT_EQ(X.get(), 12);     // 10+2
   514→    EXPECT_EQ(Y.get(), 6);      // unchanged
   515→    EXPECT_EQ(Z.get(), 18);     // 12+6
   516→    EXPECT_EQ(obs1.get(), 15);  // 12+3
   517→    EXPECT_EQ(obs2.get(), 16);  // 6+10
   518→    EXPECT_EQ(obs3.get(), 49);  // 18+15+16
   519→    EXPECT_EQ(obs4.get(), 59);  // 10+49
   520→    EXPECT_EQ(obs5.get(), 61);  // 2+59
   521→    EXPECT_EQ(obs6.get(), 113); // 3+61+49
   522→
   523→    // Trigger counts after batch1
   524→    EXPECT_EQ(triggerCountX, 1); // X recalculated
   525→    EXPECT_EQ(triggerCountY, 1); // Y unchanged
   526→    EXPECT_EQ(triggerCountZ, 1); // Z changed (depends on X)
   527→    EXPECT_EQ(triggerCountA, 1); // obs4 recalculated (depends on a)
   528→    EXPECT_EQ(triggerCountB, 1); // obs5 recalculated (depends on obs4)
   529→    EXPECT_EQ(triggerCountC, 1); // obs6 recalculated
   530→
   531→    // Reset counters for next batch
   532→    triggerCountX = triggerCountY = triggerCountZ = 0;
   533→    triggerCountA = triggerCountB = triggerCountC = 0;
   534→
   535→    batch2.execute(); // b->20, c->30
   536→
   537→    // Verify after batch2
   538→    EXPECT_EQ(a.get(), 10);
   539→    EXPECT_EQ(b.get(), 20);
   540→    EXPECT_EQ(c.get(), 30);
   541→    EXPECT_EQ(X.get(), 30);      // 10+20
   542→    EXPECT_EQ(Y.get(), 600);     // 20*30
   543→    EXPECT_EQ(Z.get(), 630);     // 30+600
   544→    EXPECT_EQ(obs1.get(), 60);   // 30+30
   545→    EXPECT_EQ(obs2.get(), 610);  // 600+10
   546→    EXPECT_EQ(obs3.get(), 1300); // 630+60+610
   547→    EXPECT_EQ(obs4.get(), 1310); // 10+1300
   548→    EXPECT_EQ(obs5.get(), 1330); // 20+1310
   549→    EXPECT_EQ(obs6.get(), 2660); // 30+1330+1300
   550→
   551→    // Trigger counts after batch2
   552→    EXPECT_EQ(triggerCountX, 1); // X recalculated (a and b changed)
   553→    EXPECT_EQ(triggerCountY, 1); // Y recalculated (b and c changed)
   554→    EXPECT_EQ(triggerCountZ, 1); // Z recalculated (X and Y changed)
   555→    EXPECT_EQ(triggerCountA, 1); // obs4 recalculated (obs3 changed)
   556→    EXPECT_EQ(triggerCountB, 1); // obs5 recalculated (obs4 changed)
   557→    EXPECT_EQ(triggerCountC, 1); // obs6 recalculated (obs5 and obs3 changed)
   558→
   559→    // Reset counters for next batch
   560→    triggerCountX = triggerCountY = triggerCountZ = 0;
   561→    triggerCountA = triggerCountB = triggerCountC = 0;
   562→
   563→    batch3.execute(); // a->100, c->300 (overriding previous changes)
   564→
   565→    // Verify after batch3
   566→    EXPECT_EQ(a.get(), 100);
   567→    EXPECT_EQ(b.get(), 20); // unchanged from batch2
   568→    EXPECT_EQ(c.get(), 300);
   569→    EXPECT_EQ(X.get(), 120);      // 100+20
   570→    EXPECT_EQ(Y.get(), 6000);     // 20*300
   571→    EXPECT_EQ(Z.get(), 6120);     // 120+6000
   572→    EXPECT_EQ(obs1.get(), 420);   // 120+300
   573→    EXPECT_EQ(obs2.get(), 6100);  // 6000+100
   574→    EXPECT_EQ(obs3.get(), 12640); // 6120+420+6100
   575→    EXPECT_EQ(obs4.get(), 12740); // 100+12640
   576→    EXPECT_EQ(obs5.get(), 12760); // 20+12740
   577→    EXPECT_EQ(obs6.get(), 25700); // 300+12760+12640
   578→
   579→    // Trigger counts after batch3
   580→    EXPECT_EQ(triggerCountX, 1); // X recalculated (a changed)
   581→    EXPECT_EQ(triggerCountY, 1); // Y recalculated (c changed)
   582→    EXPECT_EQ(triggerCountZ, 1); // Z recalculated (X and Y changed)
   583→    EXPECT_EQ(triggerCountA, 1); // obs4 recalculated (a and obs3 changed)
   584→    EXPECT_EQ(triggerCountB, 1); // obs5 recalculated (obs4 changed)
   585→    EXPECT_EQ(triggerCountC, 1); // obs6 recalculated (c, obs5, and obs3 changed)
   586→}

