    24→/**
    25→ * @brief Internal implementation of the React wrapper.
    26→ *
    27→ * This class combines expression logic, invalidation strategy, and trigger mode handling.
    28→ *
    29→ * @tparam Expr Expression type.
    30→ * @tparam Type Result value type.
    31→ * @tparam IV   Invalidation strategy.
    32→ * @tparam TR   Triggering mode.
    33→ */
    34→template <typename Expr, typename Type, IsInvalidation IV, IsTrigger TR>
    35→class ReactImpl final : public Expression<Expr, Type, TR>, public IV {
    36→public:
    37→    using Expression<Expr, Type, TR>::Expression;
    38→
    39→    /**
    40→     * @brief Assign a new value directly to the reactive variable.
    41→     * Only valid for VarExpr + non-const Type.
    42→     */
    43→    template <typename T>
    44→    void operator=(T &&t) {
    45→        value(std::forward<T>(t));
    46→    }
    47→
    48→    /// @brief Returns the current evaluated value.
    49→    [[nodiscard]] decltype(auto) get() const {
    50→        return this->getValue();
    51→    }
    52→
    53→    /// @brief Returns raw pointer to the stored object (for pointer-based types).
    54→    [[nodiscard]] auto getRaw() const {
    55→        return this->getRawPtr();
    56→    }
    57→
    58→    /**
    59→     * @brief Sets a new expression source and dependencies.
    60→     *
    61→     * @param f    Expression function/lambda.
    62→     * @param args Additional arguments (usually reactive inputs).
    63→     */
    64→    template <typename F, HasArguments... A>
    65→    void set(F &&f, A &&...args) {
    66→        this->setSource(std::forward<F>(f), std::forward<A>(args)...);
    67→        this->notify();
    68→    }
    69→
    70→    /**
    71→     * @brief Overload of set with only function input. Dependency is auto-tracked.
    72→     */
    73→    template <typename F>
    74→    void set(F &&f) {
    75→        {
    76→            RegFunGuard g([this](const NodePtr &node) {
    77→                this->addObCb(node);
    78→            });
    79→            this->setSource(std::forward<F>(f));
    80→        }
    81→        this->notify();
    82→    }
    83→
    84→    /// @brief Set a no-argument expression and auto-track dependencies.
    85→    void set() {
    86→        RegFunGuard g([this](const NodePtr &node) {
    87→            this->addObCb(node);
    88→        });
    89→        this->setOpExpr();
    90→    }
    91→
    92→    /**
    93→     * @brief Sets the actual value directly (only if convertible).
    94→     */
    95→    template <typename T>
    96→        requires(Convertable<T, Type> && IsVarExpr<Expr> && !ConstType<Type>)
    97→    void value(T &&t) {
    98→        this->setValue(std::forward<T>(t));
    99→    }
   100→
   101→    /**
   102→     * @brief Closes this reactive node and cleans up any related state.
   103→     */
   104→    void close() {
   105→        ObserverGraph::getInstance().closeNode(this->shared_from_this());
   106→        if constexpr (HasField<Type>) {
   107→            FieldGraph::getInstance().deleteObj(this->getValue().getId());
   108→        }
   109→    }
   110→
   111→    /// @brief Increases internal weak reference count.
   112→    void addWeakRef() noexcept {
   113→        m_weakRefCount++;
   114→    }
   115→
   116→    /// @brief Decreases weak reference count and invalidates if reaching zero.
   117→    void releaseWeakRef() noexcept {
   118→        if (--m_weakRefCount == 0) {
   119→            this->handleInvalid(*this);
   120→        }
   121→    }
   122→
   123→    /**
   124→     * @brief Generic atomic operation helper.
   125→     *
   126→     * @tparam F Operation function type (should take Type& and return bool indicating if changed).
   127→     * @param operation The operation to perform on the value.
   128→     * @param alwaysChanged If true, always consider the operation as changing the value.
   129→     */
   130→
   131→private:
   132→    std::atomic<int> m_weakRefCount{0}; ///< Reference counter for weak lifetime tracking.
   133→};
   134→
   135→/**
   136→ * @brief Public user-facing wrapper around the reactive node implementation.
   137→ *
   138→ * This class manages ownership, lifecycle, and convenient access to reactive values.
   139→ *
   140→ * @tparam Expr Expression type.
   141→ * @tparam Type Final value type.
   142→ * @tparam IV   Invalidation strategy.
   143→ * @tparam TR   Trigger mode type.
   144→ */
   145→template <typename Expr, typename Type, IsInvalidation IV, IsTrigger TR>
   146→class React {
   147→public:
   148→    using value_type = Type;
   149→    using react_type = ReactImpl<Expr, Type, IV, TR>;
   150→
   151→    /// @brief Construct a React from shared pointer (usually internal use).
   152→    explicit React(std::shared_ptr<react_type> ptr = nullptr) noexcept : m_weakPtr(ptr) {
   153→        safeAddRef();
   154→    }
   155→
   156→    /// @brief Destructor releases weak reference if still alive.
   157→    ~React() {
   158→        safeReleaseRef();
   159→    }
   160→
   161→    /// @brief Copy constructor.
   162→    React(const React &other) noexcept : m_weakPtr(other.m_weakPtr) {
   163→        safeAddRef();
   164→    }
   165→
   166→    /// @brief Move constructor.
   167→    React(React &&other) noexcept : m_weakPtr(std::move(other.m_weakPtr)) {
   168→        other.m_weakPtr.reset();
   169→    }
   170→
   171→    /// @brief Copy assignment with reference count handling.
   172→    React &operator=(const React &other) noexcept {
   173→        if (this != &other) {
   174→            safeReleaseRef();
   175→            m_weakPtr = other.m_weakPtr;
   176→            safeAddRef();
   177→        }
   178→        return *this;
   179→    }
   180→
   181→    /// @brief Move assignment.
   182→    React &operator=(React &&other) noexcept {
   183→        if (this != &other) {
   184→            safeReleaseRef();
   185→            m_weakPtr = std::move(other.m_weakPtr);
   186→            other.m_weakPtr.reset();
   187→        }
   188→        return *this;
   189→    }
   190→
   191→    /// @brief Compare by internal pointer name (used in containers).
   192→    bool operator<(const React &other) const {
   193→        return getName() < other.getName();
   194→    }
   195→
   196→    /// @brief Check equality by underlying object pointer.
   197→    bool operator==(const React &other) const {
   198→        return getPtr().get() == other.getPtr().get();
   199→    }
   200→
   201→    /// @brief Pointer-like access to raw value.
   202→    [[nodiscard]] auto operator->() const {
   203→        return getPtr()->getRaw();
   204→    }
   205→
   206→    /// @brief Checks if this React is valid (non-null).
   207→    [[nodiscard]] explicit operator bool() const {
   208→        return !m_weakPtr.expired();
   209→    }
   210→
   211→    /**
   212→     * @brief Value access operator.
   213→     * If within a dependency registration scope, registers node.
   214→     */
   215→    [[nodiscard]] decltype(auto) operator()() const {
   216→        REACTION_REGISTER_THREAD();
   217→        if (g_reg_fun) {
   218→            std::invoke(g_reg_fun, getPtr());
   219→        }
   220→        return get();
   221→    }
   222→
   223→    /// @brief Returns the current value.
   224→    [[nodiscard]] decltype(auto) get() const {
   225→        REACTION_REGISTER_THREAD();
   226→        return getPtr()->get();
   227→    }
   228→
   229→    /// @brief Reset the expression with new source and dependencies.
   230→    template <typename F, typename... A>
   231→    React &reset(F &&f, A &&...args) {
   232→        REACTION_REGISTER_THREAD();
   233→        if (ThreadManager::getInstance().isThreadSafetyEnabled()) {
   234→            // Use a dedicated mutex for reset operations
   235→            ConditionalUniqueLock<ConditionalMutex> lock(m_resetMutex);
   236→            auto ptr = m_weakPtr.lock();
   237→            if (!ptr) [[unlikely]] {
   238→                REACTION_THROW_NULL_POINTER("weak pointer expired during reset");
   239→            }
   240→            ptr->set(std::forward<F>(f), std::forward<A>(args)...);
   241→        } else {
   242→            // Single-threaded: direct access
   243→            auto ptr = m_weakPtr.lock();
   244→            if (!ptr) [[unlikely]] {
   245→                REACTION_THROW_NULL_POINTER("weak pointer expired during reset");
   246→            }
   247→            ptr->set(std::forward<F>(f), std::forward<A>(args)...);
   248→        }
   249→        return *this;
   250→    }
   251→
   252→    /// @brief Assigns a value (only if valid).
   253→    template <typename T>
   254→    React &value(T &&t) {
   255→        REACTION_REGISTER_THREAD();
   256→        if (g_batch_fun) {
   257→            std::invoke(g_batch_fun, getPtr());
   258→        } else {
   259→            getPtr()->value(std::forward<T>(t));
   260→        }
   261→        return *this;
   262→    }
   263→
   264→    /// @brief Apply a filter to this React node.
   265→    template <typename F, typename... A>
   266→    React &filter(F &&f, A &&...args) {
   267→        getPtr()->filter(std::forward<F>(f), std::forward<A>(args)...);
   268→        return *this;
   269→    }
   270→
   271→    /// @brief Closes this reactive node.
   272→    React &close() {
   273→        REACTION_REGISTER_THREAD();
   274→        getPtr()->close();
   275→        return *this;
   276→    }
   277→
   278→    /// @brief Assign a human-readable name for debugging/tracing.
   279→    React &setName(const std::string &name) {
   280→        ObserverGraph::getInstance().setName(getPtr(), name);
   281→        return *this;
   282→    }
   283→
   284→    /// @brief Get the name assigned to this node.
   285→    [[nodiscard]] std::string getName() const {
   286→        return ObserverGraph::getInstance().getName(getPtr());
   287→    }
   288→
   289→    // ==================== Compound Assignment Operators ====================
   290→
   291→    /// @brief Compound addition assignment operator (+=)
   292→    template <typename U>
   293→        requires(IsVarExpr<Expr> && !ConstType<Type> && AddAssignable<Type, U>)
   294→    React &operator+=(const U &rhs) {
   295→        atomicAddAssign(*getPtr(), rhs);
   296→        return *this;
   297→    }
   298→
   299→    /// @brief Compound subtraction assignment operator (-=)
   300→    template <typename U>
   301→        requires(IsVarExpr<Expr> && !ConstType<Type> && SubtractAssignable<Type, U>)
   302→    React &operator-=(const U &rhs) {
   303→        atomicSubtractAssign(*getPtr(), rhs);
   304→        return *this;
   305→    }
   306→
   307→    /// @brief Compound multiplication assignment operator (*=)
   308→    template <typename U>
   309→        requires(IsVarExpr<Expr> && !ConstType<Type> && MultiplyAssignable<Type, U>)
   310→    React &operator*=(const U &rhs) {
   311→        atomicMultiplyAssign(*getPtr(), rhs);
   312→        return *this;
   313→    }
   314→
   315→    /// @brief Compound division assignment operator (/=)
   316→    template <typename U>
   317→        requires(IsVarExpr<Expr> && !ConstType<Type> && DivideAssignable<Type, U>)
   318→    React &operator/=(const U &rhs) {
   319→        atomicDivideAssign(*getPtr(), rhs);
   320→        return *this;
   321→    }
   322→
   323→    /// @brief Compound modulo assignment operator (%=)
   324→    template <typename U>
   325→        requires(IsVarExpr<Expr> && !ConstType<Type> && ModuloAssignable<Type, U>)
   326→    React &operator%=(const U &rhs) {
   327→        atomicModuloAssign(*getPtr(), rhs);
   328→        return *this;
   329→    }
   330→
   331→    /// @brief Compound bitwise AND assignment operator (&=)
   332→    template <typename U>
   333→        requires(IsVarExpr<Expr> && !ConstType<Type> && BitwiseAndAssignable<Type, U>)
   334→    React &operator&=(const U &rhs) {
   335→        atomicBitwiseAndAssign(*getPtr(), rhs);
   336→        return *this;
   337→    }
   338→
   339→    /// @brief Compound bitwise OR assignment operator (|=)
   340→    template <typename U>
   341→        requires(IsVarExpr<Expr> && !ConstType<Type> && BitwiseOrAssignable<Type, U>)
   342→    React &operator|=(const U &rhs) {
   343→        atomicBitwiseOrAssign(*getPtr(), rhs);
   344→        return *this;
   345→    }
   346→
   347→    /// @brief Compound bitwise XOR assignment operator (^=)
   348→    template <typename U>
   349→        requires(IsVarExpr<Expr> && !ConstType<Type> && BitwiseXorAssignable<Type, U>)
   350→    React &operator^=(const U &rhs) {
   351→        atomicBitwiseXorAssign(*getPtr(), rhs);
   352→        return *this;
   353→    }
   354→
   355→    /// @brief Compound left shift assignment operator (<<=)
   356→    template <typename U>
   357→        requires(IsVarExpr<Expr> && !ConstType<Type> && LeftShiftAssignable<Type, U>)
   358→    React &operator<<=(const U &rhs) {
   359→        atomicLeftShiftAssign(*getPtr(), rhs);
   360→        return *this;
   361→    }
   362→
   363→    /// @brief Compound right shift assignment operator (>>=)
   364→    template <typename U>
   365→        requires(IsVarExpr<Expr> && !ConstType<Type> && RightShiftAssignable<Type, U>)
   366→    React &operator>>=(const U &rhs) {
   367→        atomicRightShiftAssign(*getPtr(), rhs);
   368→        return *this;
   369→    }
   370→
   371→    // ==================== Increment/Decrement Operators ====================
   372→
   373→    /// @brief Pre-increment operator (++var)
   374→    template <typename T = Type>
   375→        requires(IsVarExpr<Expr> && !ConstType<Type> && PreIncrementable<T>)
   376→    React &operator++() {
   377→        atomicIncrement(*getPtr());
   378→        return *this;
   379→    }
   380→
   381→    /// @brief Post-increment operator (var++)
   382→    template <typename T = Type>
   383→        requires(IsVarExpr<Expr> && !ConstType<Type> && PostIncrementable<T>)
   384→    Type operator++(int) {
   385→        return atomicPostIncrement(*getPtr());
   386→    }
   387→
   388→    /// @brief Pre-decrement operator (--var)
   389→    template <typename T = Type>
   390→        requires(IsVarExpr<Expr> && !ConstType<Type> && PreDecrementable<T>)
   391→    React &operator--() {
   392→        atomicDecrement(*getPtr());
   393→        return *this;
   394→    }
   395→
   396→    /// @brief Post-decrement operator (var--)
   397→    template <typename T = Type>
   398→        requires(IsVarExpr<Expr> && !ConstType<Type> && PostDecrementable<T>)
   399→    Type operator--(int) {
   400→        return atomicPostDecrement(*getPtr());
   401→    }
   402→
   403→private:
   404→    /// @brief Get the internal shared pointer for advanced operations.
   405→    [[nodiscard]] std::shared_ptr<react_type> getPtr() const {
   406→        auto ptr = m_weakPtr.lock();
   407→        if (!ptr) [[unlikely]] {
   408→            REACTION_THROW_NULL_POINTER("weak pointer lock failed");
   409→        }
   410→        return ptr;
   411→    }
   412→
   413→    /**
   414→     * @brief Safely increment the weak reference count.
   415→     *
   416→     * Only increments if the weak pointer can be locked successfully.
   417→     */
   418→    void safeAddRef() noexcept {
   419→        if (auto p = m_weakPtr.lock()) [[likely]]
   420→            p->addWeakRef();
   421→    }
   422→
   423→    /**
   424→     * @brief Safely decrement the weak reference count.
   425→     *
   426→     * Only decrements if the weak pointer can be locked successfully.
   427→     */
   428→    void safeReleaseRef() noexcept {
   429→        if (auto p = m_weakPtr.lock()) [[likely]]
   430→            p->releaseWeakRef();
   431→    }
   432→
   433→    std::weak_ptr<react_type> m_weakPtr; ///< Weak reference to the implementation node.
   434→    mutable ConditionalMutex m_resetMutex; ///< Mutex for thread-safe reset operations.
   435→
   436→    template <typename T, IsTrigger M>
   437→    friend class CalcExprBase;
   438→
   439→    friend struct FilterTrig;
   440→    friend struct std::hash<React<Expr, Type, IV, TR>>;
   441→};
   442→
   443→} // namespace reaction
   444→
   445→/// @brief Hash support for React to allow use in unordered containers.
   446→namespace std {
   447→
   448→using namespace reaction;
   449→template <typename Expr, typename Type, IsInvalidation IV, IsTrigger TR>
   450→struct hash<React<Expr, Type, IV, TR>> {
   451→    std::size_t operator()(const React<Expr, Type, IV, TR> &react) const noexcept {
   452→        return std::hash<ObserverNode *>{}(react.getPtr().get());
   453→    }
   454→};
