    10→#include <memory>
    11→#include <utility>
    12→#include "reaction/concurrency/thread_manager.h"
    13→#include "reaction/core/exception.h"
    14→#include "reaction/core/observer_node.h"
    15→#include "reaction/memory/sbo_resource.h"
    16→#include <mutex>
    17→#include <shared_mutex>
    18→
    19→namespace reaction {
    20→
    21→/**
    22→ * @brief An empty struct to represent void type in Resource specialization.
    23→ */
    24→struct Void {};
    25→
    26→// Forward declaration of ResourceImpl
    27→template <typename Type>
    28→class ResourceImpl;
    29→
    30→/**
    31→ * @brief A reactive resource wrapper managing a value of type Type.
    32→ *
    33→ * Inherits from ObserverNode, so it can participate in the reactive graph.
    34→ * Automatically uses Small Buffer Optimization (SBO) when beneficial.
    35→ *
    36→ * @tparam Type The type of the resource to manage.
    37→ */
    38→template <typename Type>
    39→class Resource : public std::conditional_t<memory::SBOTraits<Type>::is_sbo_eligible,
    40→                                           memory::SBOResource<Type>,
    41→                                           ResourceImpl<Type>>
    42→{
    43→private:
    44→    using BaseType = std::conditional_t<memory::SBOTraits<Type>::is_sbo_eligible,
    45→                                        memory::SBOResource<Type>,
    46→                                        ResourceImpl<Type>>;
    47→
    48→public:
    49→    using BaseType::BaseType; // Inherit constructors
    50→
    51→    // Expose whether this instance is using SBO
    52→    [[nodiscard]] bool isUsingSBO() const noexcept {
    53→        if constexpr (memory::SBOTraits<Type>::is_sbo_eligible) {
    54→            return static_cast<const memory::SBOResource<Type> *>(this)->isUsingSBO();
    55→        } else {
    56→            return false;
    57→        }
    58→    }
    59→};
    60→
    61→/**
    62→ * @brief Traditional heap-based resource implementation.
    63→ *
    64→ * This is the fallback implementation when SBO is not beneficial or disabled.
    65→ */
    66→template <typename Type>
    67→class ResourceImpl : public ObserverNode {
    68→public:
    69→    /**
    70→     * @brief Default constructor initializes with nullptr.
    71→     */
    72→    ResourceImpl() : m_ptr(nullptr) {
    73→    }
    74→
    75→    /**
    76→     * @brief Constructor that initializes the resource with a forwarded value.
    77→     *
    78→     * @tparam T Type of the initialization argument, constrained so it cannot be another Resource<Type>.
    79→     * @param t The initialization value for the resource.
    80→     */
    81→    template <typename T>
    82→        requires(!std::is_same_v<std::remove_cvref_t<T>, ResourceImpl<Type>>)
    83→    ResourceImpl(T &&t) : m_ptr(std::make_unique<Type>(std::forward<T>(t))) {
    84→    }
    85→
    86→    // Delete copy constructor to avoid copying unique_ptr
    87→    ResourceImpl(const ResourceImpl &) = delete;
    88→
    89→    // Delete copy assignment operator to avoid copying unique_ptr
    90→    ResourceImpl &operator=(const ResourceImpl &) = delete;
    91→
    92→    /**
    93→     * @brief Get a copy of the managed resource value in a thread-safe manner.
    94→     *
    95→     * Throws std::runtime_error if the resource is not initialized.
    96→     *
    97→     * @return Type Copy of the managed resource.
    98→     */
    99→    [[nodiscard]] Type getValue() const {
   100→        ConditionalSharedLock<ConditionalSharedMutex> lock(m_resourceMutex);
   101→        if (!m_ptr) {
   102→            REACTION_THROW_RESOURCE_NOT_INITIALIZED("Resource");
   103→        }
   104→        return *m_ptr;
   105→    }
   106→
   107→    /**
   108→     * @brief Update the managed resource with a new value.
   109→     *
   110→     * If the resource is not yet initialized, create a new one with the forwarded value.
   111→     * Otherwise, assign the forwarded value to the existing resource.
   112→     *
   113→     * @tparam T Type of the new value to update with.
   114→     * @param t The new value.
   115→     * @return true if the value changed.
   116→     */
   117→    template <typename T>
   118→    bool updateValue(T &&t) noexcept {
   119→        REACTION_REGISTER_THREAD();
   120→        ConditionalUniqueLock<ConditionalSharedMutex> lock(m_resourceMutex);
   121→        bool changed = true;
   122→        if (!m_ptr) {
   123→            m_ptr = std::make_unique<Type>(std::forward<T>(t));
   124→        } else {
   125→            if constexpr (ComparableType<Type>) {
   126→                // Create a local copy to avoid data tearing during comparison
   127→                Type newValue(std::forward<T>(t));
   128→                changed = *m_ptr != newValue;
   129→                if (changed) {
   130→                    *m_ptr = std::move(newValue);
   131→                }
   132→            } else {
   133→                *m_ptr = std::forward<T>(t);
   134→            }
   135→        }
   136→        return changed;
   137→    }
   138→
   139→    /**
   140→     * @brief Get the raw pointer to the managed resource.
   141→     *
   142→     * Throws std::runtime_error if the resource is not initialized.
   143→     *
   144→     * @return Type* Raw pointer to the resource.
   145→     */
   146→    [[nodiscard]] Type *getRawPtr() const {
   147→        ConditionalSharedLock<ConditionalSharedMutex> lock(m_resourceMutex);
   148→        if (!this->m_ptr) {
   149→            REACTION_THROW_NULL_POINTER("resource pointer access");
   150→        }
   151→        return this->m_ptr.get();
   152→    }
   153→
   154→    /**
   155→     * @brief Generic atomic operation helper.
   156→     *
   157→     * @tparam F Operation function type (should take Type& and return bool indicating if changed).
   158→     * @param operation The operation to perform on the value.
   159→     * @param alwaysChanged If true, always consider the operation as changing the value.
   160→     */
   161→    template <typename F>
   162→    void atomicOperation(F &&operation, bool alwaysChanged = false) {
   163→        REACTION_REGISTER_THREAD();
   164→        bool changed = false;
   165→        {
   166→            ConditionalUniqueLock<ConditionalSharedMutex> lock(m_resourceMutex);
   167→            try {
   168→                // Direct access to avoid lock recursion
   169→                if (!m_ptr) {
   170→                    REACTION_THROW_RESOURCE_NOT_INITIALIZED("ResourceImpl");
   171→                }
   172→
   173→                changed = operation(*m_ptr);
   174→
   175→                if (alwaysChanged) {
   176→                    changed = true;
   177→                }
   178→            } catch (const std::runtime_error&) {
   179→                // Resource not initialized, treat as no change
   180→                changed = false;
   181→            }
   182→        } // Lock is automatically released here
   183→
   184→        // Trigger notifications like ReactImpl does
   185→        if (!g_batch_execute && changed) {
   186→            this->notify(true);
   187→        }
   188→    }
   189→
   190→    /**
   191→     * @brief Always returns false for heap-based ResourceImpl.
   192→     */
   193→    [[nodiscard]] bool isUsingSBO() const noexcept {
   194→        return false;
   195→    }
   196→
   197→protected:
   198→    mutable ConditionalSharedMutex m_resourceMutex; ///< Conditional mutex for thread-safe resource access.
   199→    std::unique_ptr<Type> m_ptr;                    ///< Unique pointer managing the resource
   200→};
   201→
   202→/**
   203→ * @brief Specialization of Resource for Void type.
   204→ *
   205→ * Since Void contains no data, getValue simply returns a default constructed Void.
   206→ * Always uses SBO since no actual storage is needed.
   207→ */
   208→template <>
   209→class Resource<Void> : public ObserverNode {
   210→public:
   211→    /**
   212→     * @brief Return a default constructed Void.
   213→     *
   214→     * @return Void An empty value.
   215→     */
   216→    Void getValue() const noexcept {
   217→        return Void{};
   218→    }
   219→
   220→    /**
   221→     * @brief Always returns true for Void (no storage needed).
   222→     */
   223→    [[nodiscard]] bool isUsingSBO() const noexcept {
   224→        return true;
   225→    }
   226→};
   227→
   228→} // namespace reaction
