    16→// === Thread-Local Global State Variables ===
    17→
    18→inline thread_local std::function<void(const NodePtr &)> g_reg_fun = nullptr;
    19→inline thread_local std::function<void(const NodePtr &)> g_batch_fun = nullptr;
    20→inline thread_local bool g_batch_execute = false;
    21→
    22→// === Generic ScopedValue ===
    23→
    24→/**
    25→ * @brief RAII guard for temporarily setting a variable.
    26→ * Restores the old value automatically on destruction.
    27→ *
    28→ * @tparam T Type of the variable
    29→ */
    30→template <typename T>
    31→class ScopedValue {
    32→public:
    33→    ScopedValue(T &target, T newValue)
    34→        : ref_(target), old_(target) {
    35→        ref_ = std::move(newValue);
    36→    }
    37→
    38→    ~ScopedValue() {
    39→        ref_ = std::move(old_);
    40→    }
    41→
    42→    ScopedValue(const ScopedValue &) = delete;
    43→    ScopedValue &operator=(const ScopedValue &) = delete;
    44→
    45→private:
    46→    T &ref_;
    47→    T old_;
    48→};
    49→
    50→// === Type Aliases with Pre-bound Targets ===
    51→
    52→struct RegFunGuard : ScopedValue<std::function<void(const NodePtr &)>> {
    53→    explicit RegFunGuard(std::function<void(const NodePtr &)> fn)
    54→        : ScopedValue(g_reg_fun, std::move(fn)) {}
    55→};
    56→
    57→struct BatchFunGuard : ScopedValue<std::function<void(const NodePtr &)>> {
    58→    explicit BatchFunGuard(std::function<void(const NodePtr &)> fn)
    59→        : ScopedValue(g_batch_fun, std::move(fn)) {}
    60→};
    61→
    62→struct BatchExeGuard : ScopedValue<bool> {
    63→    explicit BatchExeGuard(bool flag)
    64→        : ScopedValue(g_batch_execute, flag) {}
    65→};
    66→
    67→// === Global State Query Functions ===
    68→
    69→[[nodiscard]] inline bool isDependencyTrackingActive() noexcept {
    70→    return g_reg_fun != nullptr;
    71→}
    72→
    73→[[nodiscard]] inline bool isBatchActive() noexcept {
    74→    return g_batch_execute;
    75→}
    76→
    77→[[nodiscard]] inline bool isBatchFunctionActive() noexcept {
    78→    return g_batch_fun != nullptr;
    79→}
    80→
    81→// === Reset Function ===
    82→
    83→inline void resetGlobalState() noexcept {
    84→    g_reg_fun = nullptr;
    85→    g_batch_fun = nullptr;
    86→    g_batch_execute = false;
    87→}
    88→
    89→} // namespace reaction
