   233→/**
   234→ * @brief Test batch reset protection mechanism
   235→ *
   236→ * This test verifies that reset operations are prevented when nodes
   237→ * are involved in active batch operations.
   238→ */
   239→TEST(BatchOperationsTest, TestBatchResetProtection) {
   240→    auto var1 = reaction::var(5).setName("var1");
   241→    auto calc1 = reaction::calc([&]() { return var1() * 2; }).setName("calc1");
   242→
   243→    // Create a batch that keeps the nodes active
   244→    std::cout << "Creating batch..." << std::endl;
   245→    auto batch = reaction::batch([&]() {
   246→        var1.value(10);
   247→    });
   248→
   249→    std::cout << "Batch created." << std::endl;
   250→
   251→    // While batch is active, reset operations should be prevented
   252→    try {
   253→        calc1.reset([&]() { return var1() + 100; });
   254→        std::cout << "Reset succeeded (unexpected)" << std::endl;
   255→        FAIL() << "Expected reset to throw exception";
   256→    } catch (const std::runtime_error &e) {
   257→        std::cout << "Reset threw exception as expected: " << e.what() << std::endl;
   258→        SUCCEED();
   259→    }
   260→
   261→    // Verify nodes still have original values
   262→    EXPECT_EQ(var1.get(), 5); // Constructor didn't change value due to BatchFunGuard
   263→    EXPECT_EQ(calc1.get(), 10);
   264→}
