   299→/**
   300→ * @brief Test complex dependency scenario with batch reset protection
   301→ *
   302→ * This test creates a complex dependency graph and verifies that
   303→ * reset operations are properly prevented during active batch operations.
   304→ */
   305→TEST(BatchOperationsTest, TestComplexDependencyBatchResetProtection) {
   306→    // Create a complex dependency graph:
   307→    // var1 -> calc1 -> calc2 -> calc3
   308→    // var2 -> calc1
   309→    //       -> calc4 -> calc5
   310→    // var3 -> calc4
   311→    //       -> calc6 -> calc7
   312→    // var4 -> calc6
   313→    //       -> calc8 -> calc9 -> calc10
   314→
   315→    auto var1 = reaction::var(1).setName("var1");
   316→    auto var2 = reaction::var(2).setName("var2");
   317→    auto var3 = reaction::var(3).setName("var3");
   318→    auto var4 = reaction::var(4).setName("var4");
   319→
   320→    auto calc1 = reaction::calc([&]() { return var1() + var2(); }).setName("calc1");
   321→    auto calc2 = reaction::calc([&]() { return calc1() * 2; }).setName("calc2");
   322→    auto calc3 = reaction::calc([&]() { return calc2() + 1; }).setName("calc3");
   323→
   324→    auto calc4 = reaction::calc([&]() { return var2() + var3(); }).setName("calc4");
   325→    auto calc5 = reaction::calc([&]() { return calc4() * 3; }).setName("calc5");
   326→
   327→    auto calc6 = reaction::calc([&]() { return var3() + var4(); }).setName("calc6");
   328→    auto calc7 = reaction::calc([&]() { return calc6() * 4; }).setName("calc7");
   329→
   330→    auto calc8 = reaction::calc([&]() { return var4() * 2; }).setName("calc8");
   331→    auto calc9 = reaction::calc([&]() { return calc8() + 5; }).setName("calc9");
   332→    auto calc10 = reaction::calc([&]() { return calc9() * 2; }).setName("calc10");
   333→
   334→    // Initial values check
   335→    EXPECT_EQ(calc1.get(), 3);   // 1 + 2
   336→    EXPECT_EQ(calc2.get(), 6);   // 3 * 2
   337→    EXPECT_EQ(calc3.get(), 7);   // 6 + 1
   338→    EXPECT_EQ(calc4.get(), 5);   // 2 + 3
   339→    EXPECT_EQ(calc5.get(), 15);  // 5 * 3
   340→    EXPECT_EQ(calc6.get(), 7);   // 3 + 4
   341→    EXPECT_EQ(calc7.get(), 28);  // 7 * 4
   342→    EXPECT_EQ(calc8.get(), 8);   // 4 * 2
   343→    EXPECT_EQ(calc9.get(), 13);  // 8 + 5
   344→    EXPECT_EQ(calc10.get(), 26); // 13 * 2
   345→
   346→    // Create a batch that affects multiple parts of the dependency graph
   347→    auto batch = reaction::batch([&]() {
   348→        var1.value(10); // Affects calc1, calc2, calc3
   349→        var2.value(20); // Affects calc1, calc4, calc5
   350→        var3.value(30); // Affects calc4, calc6, calc7
   351→        var4.value(40); // Affects calc6, calc8, calc9, calc10
   352→    });
   353→
   354→    // While batch is active, all reset operations should be prevented
   355→    EXPECT_THROW(calc1.reset([&]() { return var1() * 2; }), std::runtime_error);
   356→    EXPECT_THROW(calc2.reset([&]() { return calc1() + 10; }), std::runtime_error);
   357→    EXPECT_THROW(calc3.reset([&]() { return calc2() * 2; }), std::runtime_error);
   358→    EXPECT_THROW(calc4.reset([&]() { return var2() + var3(); }), std::runtime_error);
   359→    EXPECT_THROW(calc5.reset([&]() { return calc4() * 5; }), std::runtime_error);
   360→    EXPECT_THROW(calc6.reset([&]() { return var3() * var4(); }), std::runtime_error);
   361→    EXPECT_THROW(calc7.reset([&]() { return calc6() + 100; }), std::runtime_error);
   362→    EXPECT_THROW(calc8.reset([&]() { return var4() + 10; }), std::runtime_error);
   363→    EXPECT_THROW(calc9.reset([&]() { return calc8() * 3; }), std::runtime_error);
   364→    EXPECT_THROW(calc10.reset([&]() { return calc9() + 50; }), std::runtime_error);
   365→
   366→    // Verify values haven't changed (batch constructor doesn't execute the function)
   367→    EXPECT_EQ(calc1.get(), 3);
   368→    EXPECT_EQ(calc2.get(), 6);
   369→    EXPECT_EQ(calc3.get(), 7);
   370→
   371→    // Execute the batch
   372→    batch.execute();
   373→
   374→    // Now values should be updated
