    19→/**
    20→ * @brief Lightweight caching for observer graph traversal optimization.
    21→ *
    22→ * This cache is designed specifically for the collectObservers operation
    23→ * and DOES NOT interfere with the updateDepth mechanism or batch operations.
    24→ * It only caches the intermediate graph structure relationships, not the
    25→ * complete traversal results that require depth updates.
    26→ */
    27→class GraphTraversalCache : public PtrCacheBase<NodePtr, NodeSet> {
    28→private:
    29→    using BaseType = PtrCacheBase<NodePtr, NodeSet>;
    30→
    31→public:
    32→    GraphTraversalCache()
    33→        : BaseType(MAX_CACHE_SIZE, CACHE_TTL) {}
    34→
    35→    /**
    36→     * @brief Try to get cached immediate observers for a node.
    37→     *
    38→     * This only returns the direct observers of a node, not the full traversal.
    39→     * The caller still needs to perform the recursive traversal and depth updates.
    40→     *
    41→     * @param node The node to get immediate observers for
    42→     * @return Pointer to cached observers if valid, nullptr otherwise
    43→     */
    44→    const NodeSet *getCachedImmediateObservers(const NodePtr &node) const noexcept {
    45→        return getCachedValue(node);
    46→    }
    47→
    48→    /**
    49→     * @brief Cache immediate observers for a node.
    50→     *
    51→     * @param node The node whose immediate observers to cache
    52→     * @param observers The immediate observers (not full traversal)
    53→     */
    54→    void cacheImmediateObservers(const NodePtr &node, const NodeSet &observers) noexcept {
    55→        cacheValue(node, observers);
    56→    }
    57→
    58→    /**
    59→     * @brief Invalidate all cache entries due to graph structure change.
    60→     */
    61→    void invalidateAll() noexcept {
    62→        invalidateAllEntries();
    63→    }
    64→
    65→    /**
    66→     * @brief Get cache statistics.
    67→     */
    68→    Stats getStats() const noexcept {
    69→        return getStatsInternal();
    70→    }
    71→
    72→    /**
    73→     * @brief Trigger cleanup of expired cache entries.
    74→     */
    75→    void triggerCleanup() noexcept {
    76→        triggerCleanupInternal();
    77→    }
    78→
    79→private:
    80→    static constexpr size_t MAX_CACHE_SIZE = 500;       // Smaller cache for immediate observers only
    81→    static constexpr std::chrono::minutes CACHE_TTL{5}; // Shorter TTL
    82→};
