   103→     * @return Pointer to cached result if valid, nullptr otherwise
   104→     */
   105→    const bool *getCachedCycleResult(const NodePtr &source, const NodePtr &target) const noexcept {
   106→        return getCachedValue(std::make_pair(source, target));
