   109→    /**
   110→     * @brief Cache cycle detection result for a node pair.
   111→     *
   112→     * @param source The observing node
   113→     * @param target The node being observed
   114→     * @param hasCycle Whether adding this edge would create a cycle
   115→     */
   116→    void cacheCycleResult(const NodePtr &source, const NodePtr &target, bool hasCycle) noexcept {
   117→        cacheValue(std::make_pair(source, target), hasCycle);
   118→    }
