   123→    void invalidateAll() noexcept {
   124→        invalidateAllEntries();
   125→    }
   126→
   127→    /**
   128→     * @brief Get cache statistics.
   129→     */
   130→    Stats getStats() const noexcept {
   131→        return getStatsInternal();
   132→    }
   133→
   134→    /**
   135→     * @brief Trigger cleanup of expired cache entries.
   136→     */
   137→    void triggerCleanup() noexcept {
   138→        triggerCleanupInternal();
   139→    }
   140→
   141→private:
   142→    static constexpr size_t MAX_CYCLE_CACHE_SIZE = 1000;
   143→    static constexpr std::chrono::minutes CACHE_TTL{10};
   144→};
