    27→    // Check initial state before creating variables
    28→    bool initialState = manager.isThreadSafetyEnabled();
    29→    std::cout << "Thread safety state at test start: " << (initialState ? "Enabled" : "Disabled") << std::endl;
    30→
    31→    // Create variable and perform operations
    32→    auto var = reaction::var(42);
    33→    int value1 = var.get(); // This triggers REACTION_REGISTER_THREAD
    34→    var.value(100);
    35→    int value2 = var.get();
    36→
    37→    // Check thread safety state
    38→    bool afterSingleThread = manager.isThreadSafetyEnabled();
