   123→TEST(ThreadSafetyTest, SingleToMultiThreadTransition) {
   124→    std::cout << "=== Single-to-Multi-thread Transition Test ===" << std::endl;
   125→
   126→    auto &manager = reaction::ThreadManager::getInstance();
   127→    manager.resetForTesting();
   128→
   129→    auto sharedVar = reaction::var(0);
