    36→    auto ds = reaction::calc([](int aa, double bb) { return aa + bb; }, a, b);
    37→    auto dds = reaction::calc<reaction::FilterTrig>([](auto cc, auto dsds) { return cc + dsds; }, c, ds);
    38→    a.value(2);
    39→    EXPECT_EQ(ds.get(), 4);
    40→    EXPECT_EQ(dds.get(), 7);
    41→
    42→    dds.filter([&]() { return c() + ds() < 10; });
    43→    a.value(3);
    44→    EXPECT_EQ(dds.get(), 8);
    45→
    46→    a.value(5);
    47→    EXPECT_EQ(dds.get(), 8);
    48→}

