    39→ */
    40→template<typename Type>
    41→class SBOResource : public ObserverNode {
    42→private:
    43→    // Storage decision logic
    44→    static constexpr bool always_sbo = SBOTraits<Type>::always_sbo;
    45→    static constexpr bool conditional_sbo = SBOTraits<Type>::conditional_sbo;
    46→    static constexpr bool force_heap = SBOTraits<Type>::force_heap;
    47→
    48→    // Union for storage flexibility
    49→    union Storage {
    50→        alignas(Type) char buffer[sizeof(Type)];  // Stack storage
    51→        std::unique_ptr<Type> heap_ptr;           // Heap storage
    52→
    53→        Storage() noexcept {} // No initialization - manual lifetime management
    54→        ~Storage() noexcept {} // Manual lifetime management
    55→    } storage;
    56→
    57→    bool is_sbo_storage;  // Track which storage is active
    58→    bool is_initialized;  // Track initialization state
    59→
    60→public:
    61→    /**
    62→     * @brief Default constructor with null state.
    63→     */
    64→    SBOResource() : is_sbo_storage(false), is_initialized(false) {
    65→        // Initialize heap_ptr explicitly
    66→        new(&storage.heap_ptr) std::unique_ptr<Type>(nullptr);
    67→    }
    68→
    69→    /**
    70→     * @brief Constructor with forwarded arguments.
    71→     */
    72→    template<typename T>
    73→        requires(!std::is_same_v<std::remove_cvref_t<T>, SBOResource<Type>>)
    74→    SBOResource(T&& t) {
    75→        // Determine storage strategy first
    76→        if constexpr (SBOTraits<Type>::always_sbo) {
    77→            // Always use SBO - no heap_ptr needed
    78→            new(storage.buffer) Type(std::forward<T>(t));
    79→            is_sbo_storage = true;
    80→            is_initialized = true;
    81→        } else if constexpr (SBOTraits<Type>::conditional_sbo) {
    82→            // Conditional SBO based on stack usage
    83→            StackMonitor::StackGuard<sizeof(Type)> guard;
    84→            if (guard.success()) {
    85→                // Use SBO
    86→                new(storage.buffer) Type(std::forward<T>(t));
    87→                is_sbo_storage = true;
    88→                is_initialized = true;
    89→            } else {
    90→                // Use heap allocation
    91→                new(&storage.heap_ptr) std::unique_ptr<Type>(std::make_unique<Type>(std::forward<T>(t)));
    92→                is_sbo_storage = false;
    93→                is_initialized = true;
    94→            }
    95→        } else {
    96→            // Force heap allocation
    97→            new(&storage.heap_ptr) std::unique_ptr<Type>(std::make_unique<Type>(std::forward<T>(t)));
    98→            is_sbo_storage = false;
    99→            is_initialized = true;
   100→        }
   101→    }
   102→
   103→    /**
   104→     * @brief Destructor with proper cleanup.
   105→     */
   106→    ~SBOResource() noexcept {
   107→        destroy();
   108→    }
   109→
   110→    // Non-copyable to match original Resource behavior
   111→    SBOResource(const SBOResource&) = delete;
   112→    SBOResource& operator=(const SBOResource&) = delete;
   113→
   114→    /**
   115→     * @brief Get a copy of the stored value (thread-safe).
   116→     */
   117→    [[nodiscard]] Type getValue() const {
   118→        ConditionalSharedLock<ConditionalSharedMutex> lock(m_resourceMutex);
   119→        if (!is_initialized) {
   120→            REACTION_THROW_RESOURCE_NOT_INITIALIZED("SBOResource");
   121→        }
   122→
   123→        // Fast path for always_sbo types - eliminate runtime branch
   124→        if constexpr (always_sbo) {
   125→            return *reinterpret_cast<const Type*>(storage.buffer);
   126→        } else {
   127→            // Runtime branch for conditional_sbo types
   128→            if (is_sbo_storage) {
   129→                return *reinterpret_cast<const Type*>(storage.buffer);
   130→            } else {
   131→                return *storage.heap_ptr;
   132→            }
   133→        }
   134→    }
   135→
   136→    /**
   137→     * @brief Update the stored value.
   138→     *
   139→     * @return true if the value changed, false otherwise.
   140→     */
   141→    template<typename T>
   142→    bool updateValue(T&& t) noexcept {
   143→        REACTION_REGISTER_THREAD();
   144→        ConditionalUniqueLock<ConditionalSharedMutex> lock(m_resourceMutex);
   145→
   146→        bool changed = true;
   147→
   148→        if (!is_initialized) {
   149→            // First initialization
   150→            initializeWithImpl(std::forward<T>(t));
   151→        } else {
   152→            // Update existing value
   153→            if constexpr (ComparableType<Type>) {
   154→                // Create local copy to avoid data tearing during comparison
   155→                Type newValue(std::forward<T>(t));
   156→
   157→                // Fast path for always_sbo types - eliminate runtime branch
   158→                if constexpr (always_sbo) {
   159→                    Type* current = reinterpret_cast<Type*>(storage.buffer);
   160→                    changed = (*current != newValue);
   161→                    if (changed) {
   162→                        *current = std::move(newValue);
   163→                    }
   164→                } else {
   165→                    // Runtime branch for conditional_sbo types
   166→                    if (is_sbo_storage) {
   167→                        Type* current = reinterpret_cast<Type*>(storage.buffer);
   168→                        changed = (*current != newValue);
   169→                        if (changed) {
   170→                            *current = std::move(newValue);
   171→                        }
   172→                    } else {
   173→                        changed = (*storage.heap_ptr != newValue);
   174→                        if (changed) {
   175→                            *storage.heap_ptr = std::move(newValue);
   176→                        }
   177→                    }
   178→                }
   179→            } else {
   180→                // Non-comparable types: always assume changed
   181→                // Fast path for always_sbo types - eliminate runtime branch
   182→                if constexpr (always_sbo) {
   183→                    *reinterpret_cast<Type*>(storage.buffer) = std::forward<T>(t);
   184→                } else {
   185→                    // Runtime branch for conditional_sbo types
   186→                    if (is_sbo_storage) {
   187→                        *reinterpret_cast<Type*>(storage.buffer) = std::forward<T>(t);
   188→                    } else {
   189→                        *storage.heap_ptr = std::forward<T>(t);
   190→                    }
   191→                }
   192→            }
   193→        }
   194→
   195→        return changed;
   196→    }
   197→
   198→    /**
   199→     * @brief Get raw pointer to the stored value.
   200→     */
   201→    [[nodiscard]] Type* getRawPtr() const {
   202→        ConditionalSharedLock<ConditionalSharedMutex> lock(m_resourceMutex);
   203→        if (!is_initialized) {
   204→            REACTION_THROW_NULL_POINTER("SBOResource not initialized");
   205→        }
   206→
   207→        // Fast path for always_sbo types - eliminate runtime branch
   208→        if constexpr (always_sbo) {
   209→            return reinterpret_cast<Type*>(const_cast<char*>(storage.buffer));
   210→        } else {
   211→            // Runtime branch for conditional_sbo types
   212→            if (is_sbo_storage) {
   213→                return reinterpret_cast<Type*>(const_cast<char*>(storage.buffer));
   214→            } else {
   215→                return storage.heap_ptr.get();
   216→            }
   217→        }
   218→    }
   219→
   220→    /**
   221→     * @brief Check if this resource is using SBO storage.
   222→     */
   223→    [[nodiscard]] bool isUsingSBO() const noexcept {
   224→        return is_sbo_storage;
   225→    }
   226→
   227→    /**
   228→     * @brief Get storage information for debugging.
   229→     */
   230→    struct StorageInfo {
   231→        bool using_sbo;
   232→        bool initialized;
   233→        size_t type_size;
   234→        size_t stack_usage;
   235→    };
   236→
   237→    [[nodiscard]] StorageInfo getStorageInfo() const noexcept {
   238→        return StorageInfo{
   239→            .using_sbo = is_sbo_storage,
   240→            .initialized = is_initialized,
   241→            .type_size = sizeof(Type),
   242→            .stack_usage = is_sbo_storage ? sizeof(Type) : 0
   243→        };
   244→    }
   245→
   246→    /**
   247→     * @brief Generic atomic operation helper.
   248→     *
   249→     * @tparam F Operation function type (should take Type& and return bool indicating if changed).
   250→     * @param operation The operation to perform on the value.
   251→     * @param alwaysChanged If true, always consider the operation as changing the value.
   252→     */
   253→    template <typename F>
   254→    void atomicOperation(F &&operation, bool alwaysChanged = false) {
   255→        REACTION_REGISTER_THREAD();
   256→        bool changed = false;
   257→        {
   258→            ConditionalUniqueLock<ConditionalSharedMutex> lock(m_resourceMutex);
   259→            try {
   260→                // Direct access to avoid lock recursion
   261→                if (!is_initialized) {
   262→                    REACTION_THROW_RESOURCE_NOT_INITIALIZED("SBOResource");
   263→                }
   264→
   265→                if (is_sbo_storage) {
   266→                    Type* ptr = reinterpret_cast<Type*>(const_cast<char*>(storage.buffer));
   267→                    changed = operation(*ptr);
   268→                } else {
   269→                    changed = operation(*storage.heap_ptr);
   270→                }
   271→
   272→                if (alwaysChanged) {
   273→                    changed = true;
   274→                }
   275→            } catch (const std::runtime_error&) {
   276→                // Resource not initialized, treat as no change
   277→                changed = false;
   278→            }
   279→        } // Lock is automatically released here
   280→
   281→        // Trigger notifications like ReactImpl does
   282→        if (!g_batch_execute && changed) {
   283→            this->notify(true);
   284→        }
   285→    }
   286→
   287→private:
   288→    /**
   289→     * @brief Initialize storage with given value.
   290→     */
   291→    template<typename T>
   292→    void initializeWith(T&& t) {
   293→        try {
   294→            initializeWithImpl(std::forward<T>(t));
   295→        } catch (...) {
   296→            is_initialized = false;
   297→            is_sbo_storage = false;
   298→            throw;
   299→        }
   300→    }
   301→
   302→    /**
   303→     * @brief Internal initialization implementation.
   304→     */
   305→    template<typename T>
   306→    void initializeWithImpl(T&& t) {
   307→        if constexpr (always_sbo) {
   308→            // Always use SBO for small types
   309→            if (is_initialized && !is_sbo_storage) {
   310→                // Destroy heap_ptr if it was active from a previous state
   311→                storage.heap_ptr.~unique_ptr<Type>();
   312→            } else if (!is_initialized) {
   313→                // First time: destroy the default-constructed heap_ptr
   314→                storage.heap_ptr.~unique_ptr<Type>();
   315→            }
   316→            new(storage.buffer) Type(std::forward<T>(t));
   317→            is_sbo_storage = true;
   318→            is_initialized = true;
   319→        } else if constexpr (conditional_sbo) {
   320→            // Conditional SBO based on stack usage
   321→            StackMonitor::StackGuard<sizeof(Type)> guard;
   322→            if (guard.success()) {
   323→                // Use SBO
   324→                if (is_initialized && !is_sbo_storage) {
   325→                    // Destroy heap_ptr if it was active from a previous state
   326→                    storage.heap_ptr.~unique_ptr<Type>();
   327→                } else if (!is_initialized) {
   328→                    // First time: destroy the default-constructed heap_ptr
   329→                    storage.heap_ptr.~unique_ptr<Type>();
   330→                }
   331→                new(storage.buffer) Type(std::forward<T>(t));
   332→                is_sbo_storage = true;
   333→                is_initialized = true;
   334→            } else {
   335→                // Use heap allocation
   336→                if (is_initialized && is_sbo_storage) {
   337→                    // Destroy buffer content and re-construct heap_ptr
   338→                    reinterpret_cast<Type*>(storage.buffer)->~Type();
   339→                    new(&storage.heap_ptr) std::unique_ptr<Type>();
   340→                }
   341→                // heap_ptr is already available - either from constructor or re-construction above
   342→                storage.heap_ptr = std::make_unique<Type>(std::forward<T>(t));
   343→                is_sbo_storage = false;
   344→                is_initialized = true;
   345→            }
   346→        } else {
   347→            // Force heap allocation
   348→            if (is_initialized && is_sbo_storage) {
   349→                // Destroy buffer content and re-construct heap_ptr
   350→                reinterpret_cast<Type*>(storage.buffer)->~Type();
   351→                new(&storage.heap_ptr) std::unique_ptr<Type>();
   352→            }
   353→            // heap_ptr is already available - either from constructor or re-construction above
   354→            storage.heap_ptr = std::make_unique<Type>(std::forward<T>(t));
   355→            is_sbo_storage = false;
   356→            is_initialized = true;
   357→        }
   358→    }
   359→
   360→    /**
   361→     * @brief Destroy stored object and cleanup.
   362→     */
   363→    void destroy() noexcept {
   364→        if (is_initialized) {
   365→            if (is_sbo_storage) {
   366→                // Destroy the object in buffer
   367→                reinterpret_cast<Type*>(storage.buffer)->~Type();
   368→            } else {
   369→                // Destroy heap_ptr
   370→                storage.heap_ptr.~unique_ptr<Type>();
   371→            }
   372→            is_initialized = false;
   373→            is_sbo_storage = false;
   374→        } else {
   375→            // For uninitialized default-constructed objects, destroy heap_ptr
   376→            storage.heap_ptr.~unique_ptr<Type>();
   377→        }
   378→    }
   379→
   380→protected:
   381→    mutable ConditionalSharedMutex m_resourceMutex; ///< Thread-safe access mutex
   382→};
   383→
   384→} // namespace reaction::memory

