     8→#pragma once
     9→
    10→#include <atomic>
    11→#include <memory>
    12→#include <mutex>
    13→#include <shared_mutex>
    14→#include <thread>
    15→#include <unordered_map>
    16→
    17→// Compile-time configuration for forcing thread safety
    18→#ifndef REACTION_FORCE_THREAD_SAFETY
    19→#define REACTION_FORCE_THREAD_SAFETY 0
    20→#endif
    21→
    22→// Thread safety mode detection
    23→#ifndef REACTION_THREAD_SAFETY_MODE
    24→#if REACTION_FORCE_THREAD_SAFETY
    25→#define REACTION_THREAD_SAFETY_MODE 1 // Always thread-safe
    26→#else
    27→#define REACTION_THREAD_SAFETY_MODE 0 // Auto-detect
    28→#endif
    29→#endif
    30→
    31→namespace reaction {
    32→
    33→/**
    34→ * @brief Thread manager for automatic multi-threading detection and optimization.
    35→ *
    36→ * This singleton class manages thread safety behavior throughout the reactive system.
    37→ * It automatically detects multi-threading scenarios and enables thread safety measures
    38→ * only when needed, providing zero-overhead for single-threaded applications.
    39→ *
    40→ * Performance optimizations:
    41→ * - Thread-local caching of safety status
    42→ * - Minimal atomic operations with relaxed ordering where safe
    43→ * - Fast-path optimization for common single-threaded scenarios
    44→ */
    45→class ThreadManager {
    46→public:
    47→    /**
    48→     * @brief Get the singleton instance.
    49→     * @return ThreadManager& Reference to the singleton instance.
    50→     */
    51→    static ThreadManager &getInstance() noexcept {
    52→        static ThreadManager instance;
    53→        return instance;
    54→    }
    55→
    56→    /**
    57→     * @brief Check if thread safety is currently enabled (optimized version).
    58→     * Uses thread-local caching to avoid repeated atomic loads.
    59→     * @return true if thread safety is enabled, false otherwise.
    60→     */
    61→    bool isThreadSafetyEnabled() const noexcept {
    62→        // Use thread-local cache to avoid repeated atomic loads
    63→        static thread_local bool cached_enabled = false;
    64→        static thread_local uint32_t cached_version = 0;
    65→
    66→        uint32_t current_version = m_safetyVersion.load(std::memory_order_relaxed);
    67→        if (cached_version != current_version) [[unlikely]] {
    68→            cached_enabled = m_threadSafetyEnabled.load(std::memory_order_acquire);
    69→            cached_version = current_version;
    70→        }
    71→
    72→        return cached_enabled;
    73→    }
    74→
    75→    /**
    76→     * @brief Force enable thread safety mode.
    77→     * Once enabled, cannot be disabled during runtime.
    78→     */
    79→    void enableThreadSafety() noexcept {
    80→        bool expected = false;
    81→        if (m_threadSafetyEnabled.compare_exchange_strong(expected, true, std::memory_order_acq_rel)) {
    82→            // Increment version to invalidate thread-local caches
    83→            m_safetyVersion.fetch_add(1, std::memory_order_release);
    84→        }
    85→    }
    86→
    87→    /**
    88→     * @brief Reset thread safety state (for testing only).
    89→     * WARNING: This method should only be used in test environments.
    90→     */
    91→    void resetForTesting() noexcept {
    92→        m_threadSafetyEnabled.store(REACTION_THREAD_SAFETY_MODE, std::memory_order_release);
    93→        m_firstThreadId.store(std::thread::id{}, std::memory_order_release);
    94→        m_safetyVersion.fetch_add(1, std::memory_order_release);
    95→
    96→        // Reset current thread's registration state by forcing re-registration
    97→        forceRegisterCurrentThread();
    98→    }
    99→
   100→    /**
   101→     * @brief Register the current thread as active (optimized version).
   102→     * Automatically enables thread safety if multiple threads are detected.
   103→     * Uses thread-local state to minimize repeated registration overhead.
   104→     */
   105→    void registerThread() noexcept {
   106→        // Thread-local flag to avoid repeated registration
   107→        static thread_local bool thread_registered = false;
   108→        if (thread_registered) [[likely]] {
   109→            return;
   110→        }
   111→
   112→        std::thread::id currentId = std::this_thread::get_id();
   113→
   114→        // Fast path for already enabled thread safety
   115→        if (m_threadSafetyEnabled.load(std::memory_order_relaxed)) [[unlikely]] {
   116→            thread_registered = true;
   117→            return;
   118→        }
   119→
   120→        // Try to register as the first thread
   121→        std::thread::id expected = std::thread::id{};
   122→        if (m_firstThreadId.compare_exchange_strong(expected, currentId, std::memory_order_acq_rel)) {
   123→            // First thread registered successfully
   124→            thread_registered = true;
   125→            return;
   126→        }
   127→
   128→        // Check if it's the same thread as the first one
   129→        if (expected == currentId) [[likely]] {
   130→            // Same thread as before
   131→            thread_registered = true;
   132→            return;
   133→        }
   134→
   135→        // Different thread detected - enable thread safety
   136→        enableThreadSafety();
   137→        thread_registered = true;
   138→    }
   139→
   140→    /**
   141→     * @brief Get the number of active threads (for debugging/monitoring).
   142→     * @return size_t Number of threads that have been registered.
   143→     */
   144→    size_t getThreadCount() const noexcept {
   145→        if (!m_threadSafetyEnabled.load(std::memory_order_acquire)) {
   146→            return m_firstThreadId.load(std::memory_order_acquire) != std::thread::id{} ? 1 : 0;
   147→        }
   148→        return 2; // We know at least 2 threads exist if thread safety is enabled
   149→    }
   150→
   151→private:
   152→    /**
   153→     * @brief Force register current thread for testing (bypasses thread_local cache).
   154→     * This is a hack to work around thread_local variable persistence in tests.
   155→     */
   156→    void forceRegisterCurrentThread() noexcept {
   157→        std::thread::id currentId = std::this_thread::get_id();
   158→
   159→        // Try to register as the first thread (bypassing thread_local cache)
   160→        std::thread::id expected = std::thread::id{};
   161→        if (!m_firstThreadId.compare_exchange_strong(expected, currentId, std::memory_order_acq_rel)) {
   162→            // If another thread already registered, check if it's the same thread
   163→            if (expected != currentId) {
   164→                // Different thread detected - enable thread safety
   165→                enableThreadSafety();
   166→            }
   167→        }
   168→    }
   169→
   170→    ThreadManager() = default;
   171→    ~ThreadManager() = default;
   172→    ThreadManager(const ThreadManager &) = delete;
   173→    ThreadManager &operator=(const ThreadManager &) = delete;
   174→
   175→    std::atomic<bool> m_threadSafetyEnabled{REACTION_THREAD_SAFETY_MODE};
   176→    std::atomic<std::thread::id> m_firstThreadId{};
   177→    std::atomic<uint32_t> m_safetyVersion{1}; // Version counter for cache invalidation
   178→};
   179→
   180→/**
   181→ * @brief RAII thread registration guard.
   182→ * Automatically registers the current thread when constructed.
   183→ */
   184→class ThreadRegistrationGuard {
   185→public:
   186→    ThreadRegistrationGuard() {
   187→        ThreadManager::getInstance().registerThread();
   188→    }
   189→};
   190→
   191→// === Conditional Mutex Abstractions with Template Optimization ===
   192→
   193→/**
   194→ * @brief Unified conditional mutex wrapper with template specialization.
   195→ *
   196→ * This template automatically adapts between thread-safe and single-threaded modes
   197→ * with compile-time optimization for better performance.
   198→ *
   199→ * @tparam MutexType The underlying mutex type (std::mutex, std::shared_mutex, etc.)
   200→ */
   201→template <typename MutexType>
   202→class ConditionalMutexWrapper {
   203→public:
   204→    /// @brief Acquire lock if thread safety is enabled.
   205→    void lock() noexcept(noexcept(std::declval<MutexType>().lock())) {
   206→        if (ThreadManager::getInstance().isThreadSafetyEnabled()) [[likely]] {
   207→            m_mutex.lock();
   208→        }
   209→    }
   210→
   211→    /// @brief Release lock if thread safety is enabled.
   212→    void unlock() noexcept(noexcept(std::declval<MutexType>().unlock())) {
   213→        if (ThreadManager::getInstance().isThreadSafetyEnabled()) [[likely]] {
   214→            m_mutex.unlock();
   215→        }
   216→    }
   217→
   218→    /// @brief Try to acquire lock if thread safety is enabled.
   219→    [[nodiscard]] bool try_lock() noexcept(noexcept(std::declval<MutexType>().try_lock())) {
   220→        if (ThreadManager::getInstance().isThreadSafetyEnabled()) [[likely]] {
   221→            return m_mutex.try_lock();
   222→        }
   223→        return true; // Always succeed when thread safety is disabled
   224→    }
   225→
   226→    // Shared mutex operations (SFINAE-enabled for types that support them)
   227→    template <typename T = MutexType>
   228→    auto lock_shared() noexcept(noexcept(std::declval<T>().lock_shared()))
   229→        -> decltype(std::declval<T>().lock_shared(), void()) {
   230→        if (ThreadManager::getInstance().isThreadSafetyEnabled()) [[likely]] {
   231→            m_mutex.lock_shared();
   232→        }
   233→    }
   234→
   235→    template <typename T = MutexType>
   236→    auto unlock_shared() noexcept(noexcept(std::declval<T>().unlock_shared()))
   237→        -> decltype(std::declval<T>().unlock_shared(), void()) {
   238→        if (ThreadManager::getInstance().isThreadSafetyEnabled()) [[likely]] {
   239→            m_mutex.unlock_shared();
   240→        }
   241→    }
   242→
   243→    template <typename T = MutexType>
   244→    auto try_lock_shared() noexcept(noexcept(std::declval<T>().try_lock_shared()))
   245→        -> decltype(std::declval<T>().try_lock_shared()) {
   246→        if (ThreadManager::getInstance().isThreadSafetyEnabled()) [[likely]] {
   247→            return m_mutex.try_lock_shared();
