    13→namespace reaction {
    14→
    15→/**
    16→ * @brief Base template for invalidation strategies with CRTP optimization.
    17→ *
    18→ * @tparam Derived The derived invalidation strategy type
    19→ */
    20→template <typename Derived>
    21→struct InvalidationBase {
    22→    template <typename Source>
    23→    constexpr void handleInvalid(Source &&source) noexcept(
    24→        noexcept(static_cast<Derived *>(this)->handleInvalidImpl(std::forward<Source>(source)))) {
    25→        static_cast<Derived *>(this)->handleInvalidImpl(std::forward<Source>(source));
    26→    }
    27→};
    28→
    29→/**
    30→ * @brief Optimized close strategy with enhanced type safety.
    31→ *
    32→ * On invalidation, this strategy closes the reactive source,
    33→ * cutting off its output from the dependency graph.
    34→ */
    35→struct CloseHandle : InvalidationBase<CloseHandle> {
    36→    template <typename Source>
    37→    constexpr void handleInvalidImpl(Source &&source) {
    38→        if constexpr (IsReactSource<std::remove_cvref_t<Source>>) {
    39→            source.close();
    40→        }
    41→    }
    42→};
    43→
    44→/**
    45→ * @brief Optimized keep strategy.
    46→ *
    47→ * On invalidation, this strategy performs no action.
    48→ * The value remains unchanged and stays in the graph.
    49→ */
    50→struct KeepHandle : InvalidationBase<KeepHandle> {
    51→    template <typename Source>
    52→    constexpr void handleInvalidImpl([[maybe_unused]] Source &&source) noexcept {
    53→        // Do nothing - optimized away at compile time
    54→    }
    55→};
    56→
    57→/**
    58→ * @brief Enhanced last-value strategy with better exception safety.
    59→ *
    60→ * On invalidation, this strategy captures the last known value
    61→ * and replaces the expression with a constant returning that value.
    62→ */
    63→struct LastHandle : InvalidationBase<LastHandle> {
    64→    template <typename Source>
    65→    constexpr void handleInvalidImpl(Source &&source) {
    66→        if constexpr (IsReactSource<std::remove_cvref_t<Source>>) {
    67→            try {
    68→                auto val = source.get();
    69→                source.set([val = std::move(val)]() noexcept { return val; });
    70→            } catch (...) {
    71→                // If getting the value fails, fall back to close strategy
    72→                source.close();
    73→            }
    74→        }
