   353→    throw ExceptionType(__VA_ARGS__, __FILE__, __LINE__, __FUNCTION__)
   354→
   355→#define REACTION_THROW_DEPENDENCY_CYCLE(sourceName, targetName) \
   356→    REACTION_THROW(DependencyCycleException, sourceName, targetName)
   357→
   358→#define REACTION_THROW_SELF_OBSERVATION(nodeName) \
   359→    REACTION_THROW(SelfObservationException, nodeName)
   360→
   361→#define REACTION_THROW_NULL_POINTER(context) \
   362→    REACTION_THROW(NullPointerAccessException, context)
   363→
   364→#define REACTION_THROW_RESOURCE_NOT_INITIALIZED(resourceType) \
   365→    REACTION_THROW(ResourceNotInitializedException, resourceType)
   366→
   367→#define REACTION_THROW_TYPE_MISMATCH(expectedType, actualType) \
   368→    REACTION_THROW(TypeMismatchException, expectedType, actualType)
   369→
   370→#define REACTION_THROW_INVALID_STATE(currentState, requiredState) \
   371→    REACTION_THROW(InvalidStateException, currentState, requiredState)
   372→
   373→#define REACTION_THROW_THREAD_SAFETY_VIOLATION(operation) \
   374→    REACTION_THROW(ThreadSafetyViolationException, operation)
   375→
   376→#define REACTION_THROW_BATCH_CONFLICT(description) \
   377→    REACTION_THROW(BatchOperationConflictException, description)
   378→
   379→} // namespace reaction

