    10→#include <memory>
    11→#include <utility>
    12→#include "reaction/concurrency/thread_manager.h"
    13→#include "reaction/core/exception.h"
    14→#include "reaction/core/observer_node.h"
    15→#include "reaction/memory/sbo_resource.h"
    16→#include <mutex>
    17→#include <shared_mutex>
