    16→// === Thread-Local Global State Variables ===
    17→
    18→inline thread_local std::function<void(const NodePtr &)> g_reg_fun = nullptr;
    19→inline thread_local std::function<void(const NodePtr &)> g_batch_fun = nullptr;
