   258→/**
   259→ * @brief Expression specialization for binary expressions.
   260→ */
   261→template <typename Op, typename L, typename R, IsTrigger TR>
   262→class Expression<CalcExpr, BinaryOpExpr<Op, L, R>, TR>
   263→    : public CalcExprBase<typename BinaryOpExpr<Op, L, R>::value_type, TR> {
   264→public:
   265→    template <typename T>
   266→        requires(!std::is_same_v<std::remove_cvref_t<T>, Expression>)
   267→    Expression(T &&expr) : m_expr(std::forward<T>(expr)) {
