   923→    // Reset thread safety manager for clean test state
   924→    auto &manager = reaction::ThreadManager::getInstance();
   925→    manager.resetForTesting();
   926→
   927→    constexpr int N = 50; // Reduced from 100 for faster test execution
   928→    constexpr int NUM_OPERATIONS_PER_THREAD = 10; // Reduced for stability
   929→
   930→    // Create shared reactive objects
   931→    std::vector<reaction::Var<int>> testVars(N);
   932→    std::vector<reaction::Calc<int>> testCalcs(N);
   933→    std::vector<reaction::Action<>> testActions(N);
   934→
   935→    // Initialize reactive objects
   936→    for (int i = 0; i < N; ++i) {
   937→        testVars[i] = reaction::var(i);
   938→        testCalcs[i] = reaction::calc([]() { return 1; });
   939→        testActions[i] = reaction::action([]() {});
   940→    }
   941→
   942→    // Thread safety tracking
   943→    std::atomic<int> calcResetOperations{0};
   944→    std::atomic<int> actionResetOperations{0};
   945→    std::atomic<bool> exceptionCaught{false};
   946→    std::atomic<bool> raceConditionDetected{false};
   947→
   948→    // Thread-local random generators for each thread
   949→    auto createRandomGenerator = []() {
   950→        thread_local std::mt19937 gen(std::random_device{}());
   951→        thread_local std::uniform_int_distribution<> dist(0, N - 1);
   952→        return std::make_pair(std::ref(gen), std::ref(dist));
   953→    };
   954→
   955→    // Test function 1: Reset calculations with random dependencies
