   958→            auto [gen, dist] = createRandomGenerator();
   959→
   960→            for (int op = 0; op < NUM_OPERATIONS_PER_THREAD; ++op) {
   961→                auto rd1 = dist(gen);
   962→                auto rd2 = dist(gen);
   963→                auto rd3 = dist(gen);
   964→
   965→                // Reset calc to depend on sum of two random vars
   966→                testCalcs[rd1].reset([&testVars, rd2, rd3]() -> int {
   967→                    try {
