   993→            for (int op = 0; op < NUM_OPERATIONS_PER_THREAD; ++op) {
   994→                auto rd1 = dist(gen);
   995→                auto rd2 = dist(gen);
   996→                auto rd3 = dist(gen);
   997→
   998→                // Reset action to compute sum but don't output (for cleaner test logs)
   999→                testActions[rd1].reset([&testCalcs, rd2, rd3]() {
  1000→                    try {
  1001→                        volatile int result = testCalcs[rd2]() + testCalcs[rd3]();
  1002→                        (void)result; // Suppress unused variable warning
  1003→                    } catch (...) {
  1004→                        // Handle potential access issues gracefully
  1005→                    }
  1006→                });
  1007→
  1008→                actionResetOperations.fetch_add(1, std::memory_order_relaxed);
  1009→
  1010→                // Small yield to increase contention
  1011→                std::this_thread::yield();
  1012→            }
  1013→        } catch (const std::exception &e) {
  1014→            std::cerr << "Exception in actionResetTest: " << e.what() << std::endl;
  1015→            exceptionCaught.store(true, std::memory_order_relaxed);
  1016→        } catch (...) {
  1017→            std::cerr << "Unknown exception in actionResetTest" << std::endl;
  1018→            exceptionCaught.store(true, std::memory_order_relaxed);
  1019→        }
  1020→    };
  1021→
  1022→    std::cout << "Starting " << N << " calc reset threads and " << N << " action reset threads..." << std::endl;
  1023→
