    37→void demonstrateDependencyCycleException() {
    38→    printSection("Dependency Cycle / Self-Observation Exception");
    39→
    40→    std::cout << "Demonstrating both self-observation and dependency cycle detection...\n";
    41→
    42→    // First, demonstrate self-observation
    43→    std::cout << "\n--- Self-Observation Example ---\n";
    44→    try {
    45→        auto a = var(10).setName("variable_a");
    46→        auto calcA = calc([&]() { return a() + 1; }).setName("calc_a");
    47→
    48→        std::cout << "Attempting to create self-observation...\n";
    49→        calcA.reset([&]() { return calcA() + a(); }); // This creates self-observation
    50→
    51→        std::cout << "❌ No exception was thrown for self-observation!\n";
    52→
    53→    } catch (const SelfObservationException &e) {
    54→        std::cout << "✅ Caught SelfObservationException: " << e.what() << "\n";
    55→    } catch (const ReactionException &e) {
    56→        std::cout << "✅ Caught ReactionException: " << e.what() << "\n";
    57→    }
    58→
    59→    // Second, demonstrate dependency cycle (A -> B -> A)
    60→    std::cout << "\n--- Dependency Cycle Example ---\n";
    61→    try {
    62→        auto a = var(1).setName("A");
    63→        auto b = var(2).setName("B");
    64→
    65→        // Create interdependent calculations
    66→        auto calcA = calc([&]() { return b() + 1; }).setName("calc_A");
    67→        auto calcB = calc([&]() { return a() + 1; }).setName("calc_B");
    68→
    69→        std::cout << "Created interdependent calculations A and B\n";
    70→        std::cout << "Current values - A: " << calcA.get() << ", B: " << calcB.get() << "\n";
    71→
    72→        // Now try to make them truly interdependent by updating dependencies
    73→        // This should be detected as a cycle during dependency resolution
    74→        std::cout << "Attempting operations that might reveal cycles...\n";
    75→
    76→        // Force evaluation and dependency tracking
    77→        int valA = calcA.get();
    78→        int valB = calcB.get();
    79→        std::cout << "Evaluated values - A: " << valA << ", B: " << valB << "\n";
    80→
    81→        // The cycle might be detected during subsequent operations
    82→        a.value(10); // This might trigger cycle detection
    83→        std::cout << "Successfully updated variable A\n";
    84→
    85→    } catch (const DependencyCycleException &e) {
    86→        std::cout << "✅ Caught DependencyCycleException: " << e.what() << "\n";
    87→    } catch (const ReactionException &e) {
    88→        std::cout << "✅ Caught ReactionException: " << e.what() << "\n";
    89→    }
    90→}
