   179→void demonstrateBatchOperationConflicts() {
   180→    printSection("Batch Operation Conflicts Exception");
   181→
   182→    std::cout << "Demonstrating batch operation conflict detection...\n";
   183→
   184→    auto counter = var(0).setName("counter");
   185→    auto tempCalc = calc([&]() { return counter() * 2; }).setName("temp_calc");
   186→
   187→    std::cout << "Initial tempCalc value: " << tempCalc.get() << "\n";
   188→
   189→    // Test batch operation conflict - reset operations during batch execution throw exceptions
   190→    std::cout << "\nTesting batch operation conflict (reset within batch):\n";
   191→    try {
   192→        batchExecute([&]() {
   193→            counter.value(1);
   194→            std::cout << "Updated counter within batch\n";
   195→
   196→            // Reset within batch - this should throw BatchOperationConflictException
   197→            std::cout << "Attempting to reset calculation within active batch...\n";
   198→            tempCalc.reset([&]() { return counter() + 10; });
   199→        });
   200→
   201→        std::cout << "Batch operation completed\n";
   202→
   203→    } catch (const BatchOperationConflictException &e) {
   204→        std::cout << "✅ Caught BatchOperationConflictException: " << e.what() << "\n";
   205→    } catch (const ReactionException &e) {
   206→        std::cout << "✅ Caught ReactionException: " << e.what() << "\n";
   207→    }
   208→
   209→    // Test normal batch operation (no conflicts)
   210→    std::cout << "\nTesting normal batch operation (no conflicts):\n";
   211→    try {
   212→        batchExecute([&]() {
   213→            counter.value(5);
   214→            std::cout << "✅ Normal batch operation succeeded - tempCalc: " << tempCalc.get() << "\n";
   215→        });
   216→        std::cout << "Batch operation completed successfully\n";
   217→        std::cout << "Final tempCalc value: " << tempCalc.get() << "\n";
   218→    } catch (const ReactionException &e) {
   219→        std::cout << "⚠️  Unexpected exception in normal batch: " << e.what() << "\n";
   220→    }
   221→}
