   223→void demonstrateExceptionPropagation() {
   224→    printSection("Exception Propagation in Reactive Chains");
   225→
   226→    std::cout << "Demonstrating how exceptions propagate through reactive chains...\n";
   227→
   228→    try {
   229→        // Create a chain: var -> calc -> action
   230→        auto source = var(10).setName("source");
   231→        auto multiplier = calc([&]() {
   232→            int val = source();
   233→            if (val < 0) {
   234→                throw std::runtime_error("Negative values not allowed in multiplier");
   235→            }
   236→            return val * 2;
   237→        }).setName("multiplier");
   238→
   239→        auto logger = action([&]() {
   240→            try {
   241→                std::cout << "Multiplier result: " << multiplier() << "\n";
   242→            } catch (const std::runtime_error &e) {
   243→                std::cout << "⚠️  Runtime error in action: " << e.what() << "\n";
   244→                throw; // Re-throw to demonstrate propagation
   245→            }
   246→        }).setName("logger");
   247→
   248→        // Test normal operation
   249→        std::cout << "Testing normal operation:\n";
   250→        source.value(5);
   251→
   252→        // Test error propagation
   253→        std::cout << "\nTesting error propagation:\n";
   254→        source.value(-1);
   255→
   256→    } catch (const ReactionException &e) {
   257→        std::cout << "✅ Caught ReactionException: " << e.what() << "\n";
   258→    } catch (const std::runtime_error &e) {
   259→        std::cout << "✅ Caught runtime_error: " << e.what() << "\n";
   260→    }
   261→}
