    11→// Test basic calculation functionality with different types
    12→TEST(BasicOperationsTest, TestCalc) {
    13→    auto a = reaction::var(1);
    14→    auto b = reaction::var(3.14);
    15→    EXPECT_EQ(a.get(), 1);
    16→    EXPECT_EQ(b.get(), 3.14);
    17→
    18→    auto ds = reaction::calc([](int aa, double bb) { return aa + bb; }, a, b);
    19→    auto dds = reaction::calc([](int aa, double dsds) { return std::to_string(aa) + std::to_string(dsds); }, a, ds);
    20→    auto ddds = reaction::calc([]() { return 1; });
    21→
    22→    ASSERT_FLOAT_EQ(ds.get(), 4.14);
    23→    EXPECT_EQ(dds.get(), "14.140000");
    24→    EXPECT_EQ(ddds.get(), 1);
    25→}
    26→
    27→// Test reactive value updates and triggering
    28→TEST(BasicOperationsTest, TestTrigger) {
    29→    auto a = reaction::var(1);
    30→    auto b = reaction::var(3.14);
    31→    EXPECT_EQ(a.get(), 1);
    32→    EXPECT_EQ(b.get(), 3.14);
    33→
    34→    auto ds = reaction::calc([](int aa, double bb) { return aa + bb; }, a, b);
    35→    auto dds = reaction::calc([](auto aa, auto dsds) { return std::to_string(aa) + std::to_string(dsds); }, a, ds);
    36→
    37→    ASSERT_FLOAT_EQ(ds.get(), 4.14);
    38→    EXPECT_EQ(dds.get(), "14.140000");
    39→
    40→    a.value(2);
