    19→// Test data structures for SBO testing
    20→struct SmallStruct {
    21→    int x, y;
    22→    SmallStruct(int x = 0, int y = 0) : x(x), y(y) {}
    23→    bool operator==(const SmallStruct& other) const {
    24→        return x == other.x && y == other.y;
    25→    }
    26→    bool operator!=(const SmallStruct& other) const {
    27→        return !(*this == other);
    28→    }
