    30→
    31→struct MediumStruct {
    32→    double data[4];  // 32 bytes
    33→    MediumStruct(double val = 0.0) {
    34→        for (int i = 0; i < 4; ++i) data[i] = val + i;
    35→    }
    36→    bool operator==(const MediumStruct& other) const {
    37→        for (int i = 0; i < 4; ++i) {
