    15→/**
    16→ * @brief Base template for invalidation strategies with CRTP optimization.
    17→ *
    18→ * @tparam Derived The derived invalidation strategy type
    19→ */
    20→template <typename Derived>
    21→struct InvalidationBase {
    22→    template <typename Source>
    23→    constexpr void handleInvalid(Source &&source) noexcept(
    24→        noexcept(static_cast<Derived *>(this)->handleInvalidImpl(std::forward<Source>(source)))) {
    25→        static_cast<Derived *>(this)->handleInvalidImpl(std::forward<Source>(source));
    26→    }
    27→};
