   310→class ThreadSafetyViolationException : public ReactionException {
   311→public:
   312→    ThreadSafetyViolationException(const std::string &operation,
   313→        const std::string &file = "",
   314→        int line = 0,
   315→        const std::string &function = "")
   316→        : ReactionException(
   317→              "Thread safety violation during " + operation,
   318→              ErrorCode::THREAD_SAFETY_VIOLATION, file, line, function),
   319→          m_operation(operation) {
   320→    }
   321→
   322→    const std::string &getOperation() const noexcept { return m_operation; }
   323→
   324→private:
   325→    std::string m_operation;
   326→};
