   328→/**
   329→ * @brief Exception thrown when there's a conflict with batch operations.
   330→ */
   331→class BatchOperationConflictException : public ReactionException {
   332→public:
   333→    BatchOperationConflictException(const std::string &conflictDescription,
   334→        const std::string &file = "",
   335→        int line = 0,
   336→        const std::string &function = "")
   337→        : ReactionException(
   338→              "Batch operation conflict: " + conflictDescription,
   339→              ErrorCode::BATCH_OPERATION_CONFLICT, file, line, function),
   340→          m_conflictDescription(conflictDescription) {
