     9→
    10→#include "reaction/concurrency/thread_manager.h"
    11→#include "reaction/core/types.h"
    12→#include <atomic>
    13→#include <memory>
    14→#include <mutex>
    15→#include <shared_mutex>
    16→#include <vector>
    17→
    18→namespace reaction {
    19→
    20→// Forward declarations
    21→class ObserverGraph;
    22→
    23→/**
    24→ * @brief Reactive graph node base class.
    25→ *
    26→ * All reactive nodes should inherit from this base.
    27→ * It manages notification propagation and observer lists.
    28→ */
    29→class ObserverNode : public std::enable_shared_from_this<ObserverNode> {
    30→public:
    31→    virtual ~ObserverNode() = default;
    32→
    33→    /**
    34→     * @brief Trigger downstream notifications.
    35→     *
    36→     * By default, triggers notify().
    37→     * @param changed Whether the node's value has changed.
    38→     */
    39→    virtual void valueChanged(bool changed = true) {
    40→        this->notify(changed);
    41→    }
    42→
    43→    /**
    44→     * @brief Handle value change without triggering downstream notifications.
    45→     *
    46→     * This method is called when a node's value changes but we don't want
    47→     * to immediately propagate the change to observers. This is useful in
    48→     * batch operations where notifications are deferred until the end.
    49→     *
    50→     * @param changed Whether the node's value has actually changed (default: true)
    51→     */
    52→    virtual void changedNoNotify([[maybe_unused]] bool changed = true) {}
    53→
    54→    /**
    55→     * @brief Update the depth of this node in the reactive dependency graph.
    56→     *
    57→     * The depth represents how many levels deep this node is in the dependency chain.
    58→     * This is used for ordering nodes during batch operations and cycle detection.
    59→     * The depth is set to the maximum of the current depth and the provided depth.
    60→     *
    61→     * @param depth The new depth value to consider
    62→     */
    63→    void updateDepth(uint16_t depth) noexcept {
    64→        REACTION_REGISTER_THREAD();
    65→        if (ThreadManager::getInstance().isThreadSafetyEnabled()) {
    66→            // Use atomic compare-and-swap for thread-safe depth updates
    67→            uint16_t currentDepth = m_depth.load(std::memory_order_relaxed);
    68→            uint16_t newDepth = std::max(depth, currentDepth);
    69→            while (newDepth > currentDepth && 
    70→                   !m_depth.compare_exchange_weak(currentDepth, newDepth, std::memory_order_relaxed)) {
    71→                newDepth = std::max(depth, currentDepth);
    72→            }
    73→        } else {
    74→            // Single-threaded: direct assignment
    75→            m_depth.store(std::max(depth, m_depth.load(std::memory_order_relaxed)), std::memory_order_relaxed);
    76→        }
    77→    }
    78→
    79→    /**
    80→     * @brief Update all observer dependencies at once.
    81→     *
    82→     * Resets current observers, then adds given nodes as new observers.
    83→     * @tparam Args Parameter pack for node pointers.
    84→     * @param args Nodes to observe.
    85→     */
    86→    template <typename... Args>
    87→    void updateObservers(Args &&...args);
    88→
    89→    /**
    90→     * @brief Add a single observer node.
    91→     * @param node Observer node to add.
    92→     */
    93→    void addOneObserver(const NodePtr &node);
    94→
    95→    /**
    96→     * @brief Notify observers and delayed repeat nodes.
    97→     * @param changed Whether the node's value has changed.
    98→     */
    99→    void notify(bool changed = true) {
   100→        if (ThreadManager::getInstance().isThreadSafetyEnabled()) {
   101→            // Copy observers under lock to avoid holding lock during callbacks
   102→            std::vector<std::shared_ptr<ObserverNode>> observersCopy;
   103→            {
   104→                ConditionalSharedLock<ConditionalSharedMutex> lock(m_observersMutex);
   105→                observersCopy.reserve(m_observers.size());
   106→                for (auto &observer : m_observers) {
   107→                    if (auto wp = observer.lock()) [[likely]] {
   108→                        observersCopy.push_back(wp);
   109→                    }
   110→                }
   111→            }
   112→
   113→            // Notify observers outside of lock to avoid deadlocks
   114→            for (auto &observer : observersCopy) {
   115→                observer->valueChanged(changed);
   116→            }
   117→        } else {
   118→            // Single-threaded mode: no need to copy, direct iteration
   119→            for (auto &observer : m_observers) {
   120→                if (auto wp = observer.lock()) [[likely]]
   121→                    wp->valueChanged(changed);
   122→            }
   123→        }
   124→    }
   125→
   126→private:
   127→    std::atomic<uint16_t> m_depth{0};               ///< Depth of the node in reactive chain.
   128→    mutable ConditionalSharedMutex m_observersMutex; ///< Conditional mutex for thread-safe observers access.
   129→    NodeSet m_observers;                             ///< Direct observers of this node.
   130→    friend class ObserverGraph;
   131→    friend struct BatchCompare;
   132→};
   133→
   134→} // namespace reaction
   135→
   136→// Implementation of methods that require ObserverGraph
   137→#include "reaction/graph/observer_graph.h"
   138→
   139→namespace reaction {
   140→
   141→template <typename... Args>
   142→inline void ObserverNode::updateObservers(Args &&...args) {
   143→    auto shared_this = shared_from_this();
   144→    ObserverGraph::getInstance().updateObserversTransactional(shared_this, args...);
   145→}
   146→
   147→inline void ObserverNode::addOneObserver(const NodePtr &node) {
   148→    ObserverGraph::getInstance().addObserver(shared_from_this(), node);
   149→}
   150→
   151→} // namespace reaction
