    20→/**
    21→ * @brief Enhanced base template for expression evaluation with optimized performance.
    22→ *
    23→ * Uses CRTP pattern for zero-cost abstraction and compile-time polymorphism.
    24→ *
    25→ * @tparam Derived The derived expression type (CRTP)
    26→ * @tparam ValueType The type of value this expression evaluates to
    27→ */
    28→template <typename Derived, typename ValueType>
    29→class ExpressionBase {
    30→public:
    31→    using value_type = ValueType;
    32→
    33→    /// @brief Evaluates the expression by calling the derived implementation.
    34→    [[nodiscard]] constexpr auto operator()() const
    35→        noexcept(noexcept(static_cast<const Derived *>(this)->evaluate())) {
    36→        return static_cast<const Derived *>(this)->evaluate();
    37→    }
    38→
    39→    /// @brief Implicit conversion to value type (evaluates expression).
    40→    [[nodiscard]] constexpr operator value_type() const
    41→        noexcept(noexcept(static_cast<const Derived *>(this)->evaluate())) {
    42→        return static_cast<const Derived *>(this)->evaluate();
    43→    }
    44→
    45→    /// @brief Explicit evaluation method for clarity.
    46→    [[nodiscard]] constexpr auto evaluate() const
    47→        noexcept(noexcept(static_cast<const Derived *>(this)->evaluate())) {
    48→        return static_cast<const Derived *>(this)->evaluate();
    49→    }
    50→};
    51→
    52→/**
    53→ * @brief Optimized wrapper for literal values into callable expressions.
    54→ *
    55→ * Provides zero-overhead abstraction for constant values in expression trees.
    56→ *
    57→ * @tparam T Value type.
    58→ */
    59→template <typename T>
    60→struct ValueWrapper : ExpressionBase<ValueWrapper<T>, std::remove_cvref_t<T>> {
    61→    using value_type = std::remove_cvref_t<T>;
    62→
    63→    static_assert(!std::is_reference_v<T>, "ValueWrapper should not store references");
    64→
    65→    T m_value;
    66→
    67→    template <typename Type>
    68→        requires Convertable<Type, T>
    69→    constexpr ValueWrapper(Type &&t) noexcept(std::is_nothrow_constructible_v<T, Type>)
    70→        : m_value(std::forward<Type>(t)) {}
    71→
    72→    [[nodiscard]] constexpr const T &evaluate() const noexcept {
    73→        return m_value;
    74→    }
    75→
    76→    [[nodiscard]] constexpr const T &getValue() const noexcept {
    77→        return m_value;
    78→    }
    79→};
