   211→     * @brief Invalidate all cache entries due to graph structure change.
   212→     */
   213→    void invalidateAll() noexcept {
   214→        this->invalidateAllEntries();
   215→    }
   216→
   217→    /**
   218→     * @brief Get cache statistics.
   219→     */
   220→    typename BaseType::Stats getStats() const noexcept {
   221→        return this->getStatsInternal();
   222→    }
   223→
   224→    /**
   225→     * @brief Trigger cleanup of expired cache entries.
   226→     */
   227→    void triggerCleanup() noexcept {
   228→        this->triggerCleanupInternal();
   229→    }
   230→
   231→private:
   232→    static constexpr size_t MAX_METRICS_CACHE_SIZE = 800;
   233→    static constexpr std::chrono::minutes CACHE_TTL{8};
   234→};
