   260→/**
   261→ * @brief Specialized cache base for pair key types.
   262→ *
   263→ * Uses alias template for cleaner and more efficient implementation.
   264→ *
   265→ * @tparam First The first type in the pair
   266→ * @tparam Second The second type in the pair
   267→ * @tparam Value The value type to cache
   268→ */
   269→template <typename First, typename Second, typename Value>
   270→using PairCacheBase = CacheBase<
   271→    std::pair<First, Second>,
   272→    Value,
   273→    std::hash<std::pair<First, Second>>,
   274→    std::equal_to<std::pair<First, Second>>>;
   275→
   276→} // namespace reaction
   277→
   278→// Specialize std::hash for std::pair to support PairCacheBase
   279→namespace std {
   280→template <typename T1, typename T2>
   281→struct hash<std::pair<T1, T2>> {
   282→    size_t operator()(const std::pair<T1, T2> &p) const noexcept {
   283→        auto h1 = std::hash<T1>{}(p.first);
   284→        auto h2 = std::hash<T2>{}(p.second);
   285→        return h1 ^ (h2 << 1);
   286→    }
   287→};
   288→} // namespace std

