    24→/**
    25→ * @brief RAII guard for temporarily setting a variable.
    26→ * Restores the old value automatically on destruction.
    27→ *
    28→ * @tparam T Type of the variable
    29→ */
    30→template <typename T>
    31→class ScopedValue {
    32→public:
    33→    ScopedValue(T &target, T newValue)
    34→        : ref_(target), old_(target) {
    35→        ref_ = std::move(newValue);
    36→    }
    37→
    38→    ~ScopedValue() {
    39→        ref_ = std::move(old_);
    40→    }
    41→
    42→    ScopedValue(const ScopedValue &) = delete;
    43→    ScopedValue &operator=(const ScopedValue &) = delete;
    44→
    45→private:
    46→    T &ref_;
    47→    T old_;
    48→};
    49→
    50→// === Type Aliases with Pre-bound Targets ===
    51→
    52→struct RegFunGuard : ScopedValue<std::function<void(const NodePtr &)>> {
