    61→ *
    62→ * Handles dependency registration, invalidation, and value recomputation.
    63→ *
    64→ * @tparam Type Computed value type.
    65→ * @tparam TR   Triggering mode.
    66→ */
    67→template <typename Type, IsTrigger TR>
    68→class CalcExprBase : public Resource<Type>, public TR {
    69→public:
    70→    /**
    71→     * @brief Sets the function source and its dependencies transactionally.
    72→     *
    73→     * This method ensures atomicity: either all changes succeed,
    74→     * or the node is restored to its original consistent state.
    75→     */
    76→    template <typename F, typename... A>
    77→    void setSource(F &&f, A &&...args) {
    78→        if constexpr (std::convertible_to<ReturnType<F, A...>, Type>) {
    79→            // Check if node is involved in any active batch operations
    80→            auto shared_this = std::static_pointer_cast<CalcExprBase<Type, TR>>(this->shared_from_this());
    81→            if (ObserverGraph::getInstance().isNodeInActiveBatch(shared_this)) {
    82→                REACTION_THROW_BATCH_CONFLICT("Reset operations must be performed outside of batch contexts");
    83→            }
    84→
    85→            ConditionalUniqueLock<ConditionalSharedMutex> lock(m_functionMutex);
    86→
    87→            auto originalFun = std::move(m_fun);
    88→            auto originalValue = [this]() -> std::optional<Type> {
    89→                if constexpr (!VoidType<Type>) {
    90→                    // Safely get value without throwing if not initialized
    91→                    try {
    92→                        return this->getValue();
    93→                    } catch (const std::runtime_error &) {
    94→                        return std::nullopt;
    95→                    }
    96→                } else {
    97→                    return std::nullopt;
    98→                }
    99→            }();
   100→
   101→            auto observerRollback = ObserverGraph::getInstance().saveNodeStateForRollback(shared_this);
   102→
   103→            try {
   104→                // Create new function first
   105→                auto newFun = createFun(std::forward<F>(f), std::forward<A>(args)...);
   106→
   107→                // Update observers with new dependencies
   108→                this->updateObservers(args.getPtr()...);
   109→
   110→                // Replace the function
   111→                m_fun = std::move(newFun);
   112→
   113→                // Now evaluate with the new function
   114→                if constexpr (!VoidType<Type>) {
   115→                    this->updateValue(evaluateInternal());
   116→                } else {
   117→                    evaluateInternal();
   118→                }
   119→
   120→            } catch (const std::exception &) {
   121→                // Rollback on failure
   122→                m_fun = originalFun;
   123→
   124→                // Restore original value if it exists
   125→                if constexpr (!VoidType<Type>) {
   126→                    if (originalValue.has_value()) {
   127→                        this->updateValue(*originalValue);
   128→                    }
   129→                }
   130→
   131→                // Restore original observer state
   132→                observerRollback();
   133→
   134→                throw; // Re-throw the original exception
   135→            }
   136→        } else {
   137→            REACTION_THROW_TYPE_MISMATCH(typeid(Type).name(), typeid(ReturnType<F, A...>).name());
   138→        }
   139→    }
   140→
   141→    /// @brief Registers an observer for dependency tracking.
   142→    void addObCb(const NodePtr &node) {
   143→        this->addOneObserver(node);
   144→    }
   145→
   146→    /// @brief Handles value change notifications and trigger checks.
   147→    void valueChanged(bool changed) override {
   148→        handleChange<true>(changed);
   149→    }
   150→
   151→    /// @brief Handles value change without notifications.
   152→    void changedNoNotify(bool changed) override {
   153→        handleChange<false>(changed);
   154→    }
